INSERT INTO `topic_points` VALUES (1057, 11, 4, NULL, '第七讲人工智能前沿技术', NULL, NULL, '掌握人工智能领域最新技术发展趋势与应用前景', 2, 0, '2025-06-28 19:41:53', '2025-06-28 19:41:53');
INSERT INTO `topic_points` VALUES (1058, 11, 4, 1, '人工智能通识课', '理论教学内容', '理论教学内容', '人工智能通识课程知识体系', 1, 0, '2025-06-28 19:41:53', '2025-06-28 19:41:53');
INSERT INTO `topic_points` VALUES (1059, 11, 4, NULL, '强化学习基础', '第七讲', '第七讲', '马尔可夫决策过程、Q学习、策略梯度等强化学习核心技术', 3, 0, '2025-06-28 19:41:53', '2025-06-28 19:41:53');
INSERT INTO `topic_points` VALUES (1060, 11, 4, 2, '第一讲认识人工智能', NULL, NULL, '能阐述人工智能的核心概念与技术分类；能分析人工智能发展的关键里程碑与社会驱动力。', 2, 0, '2025-06-28 19:41:53', '2025-06-28 19:41:53');
INSERT INTO `topic_points` VALUES (1061, 11, 4, NULL, '联邦学习技术', '第七讲', '第七讲', '分布式机器学习框架、隐私保护与模型聚合方法', 3, 0, '2025-06-28 19:41:53', '2025-06-28 19:41:53');
INSERT INTO `topic_points` VALUES (1062, 11, 4, 3, '第二讲人工智能基础理论', NULL, NULL, '能运用语言逻辑等表示方法来表达简单知识；能使用基础搜索算法解决问题；能使用群智能算法完成对复杂问题的优化。', 2, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1063, 11, 4, NULL, '量子机器学习导论', '第七讲', '第七讲', '量子计算基础、量子神经网络原理与混合量子-经典算法', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1064, 11, 4, 4, '第三讲人工智能与计算思维', NULL, NULL, '掌握人工智能基本概念；学习基本计算思维方法。', 2, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1065, 11, 4, 5, '第四讲深度学习与大数据', NULL, NULL, '能绘制神经网络基础结构图（感知机制、反向传播、激活函数）；掌握深度学习模型的调试策略和技巧。', 2, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1066, 11, 4, 6, '第五讲人工智能的经典及前沿应用', NULL, NULL, '学会专家系统工具及应用；掌握计算机视觉模型和关键技术；学会自然语言处理基本方法；能描述生成式AI的核心原理；能理解\"AI+垂直领域\"创新应用原理。', 2, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1067, 11, 4, 7, '第六讲人工智能安全与伦理', NULL, NULL, '能分析AI技术伦理与安全的典型问题；能提出应对AI失效风险的可行性建议。', 2, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1068, 11, 4, 8, '人工智能的定义与技术分类（修正）', '第一讲', '第一讲', '人工智能基本概念、技术分类体系（基于规则/统计/连接主义等）', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1069, 11, 4, 9, '人工智能发展简史', '第一讲', '第一讲', '从图灵测试到深度学习革命的关键发展历程', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1070, 11, 4, 10, '人工智能主要流派', '第一讲', '第一讲', '符号主义、连接主义、行为主义学派的核心理论与代表人物', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1071, 11, 4, 11, '知识表示方法', '第二讲', '第二讲', '谓词逻辑、产生式表示、框架理论、语义网等知识表示技术', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1072, 11, 4, 12, '搜索技术', '第二讲', '第二讲', '图搜索策略；盲目搜索（DFS/BFS）；启发式搜索（A*）；博弈搜索（Minimax）', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1073, 11, 4, 13, '群智能算法', '第二讲', '第二讲', '遗传算法；粒子群优化算法；蚁群算法的原理与应用', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1074, 11, 4, 14, '人工智能的数学本质', '第三讲', '第三讲', 'AI背后的数学原理：概率论、线性代数、优化理论', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1075, 11, 4, 15, '人工智能中的简化数学', '第三讲', '第三讲', '面向AI应用的数学简化方法与计算优化', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1076, 11, 4, 16, '计算思维方法基础', '第三讲', '第三讲', '问题分解、模式识别、抽象化、算法设计等核心计算思维', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1077, 11, 4, 17, '神经网络基础', '第四讲', '第四讲', '感知机、反向传播算法、激活函数（Sigmoid, ReLU, Tanh）', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1078, 11, 4, 18, '典型深度神经网络', '第四讲', '第四讲', '卷积神经网络（CNN）、循环神经网络（RNN/LSTM）架构与应用', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1079, 11, 4, 19, '大模型原理', '第四讲', '第四讲', 'Transformer架构核心机制；预训练与微调技术；注意力机制', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1080, 11, 4, 20, '专家系统应用', '第五讲', '第五讲', '医学诊断、农业专家系统等领域的规则引擎与知识库构建', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1081, 11, 4, 21, '计算机视觉技术', '第五讲', '第五讲', '目标检测（YOLO/SSD）、图像分割（Mask R-CNN）等CV核心技术', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1082, 11, 4, 22, '自然语言系统', '第五讲', '第五讲', '机器翻译、情感分析等NLP任务的技术实现', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1083, 11, 4, 23, '生成式AI', '第五讲', '第五讲', '生成对抗网络（GAN）、扩散模型等生成式技术原理', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1084, 11, 4, 24, '具身智能', '第五讲', '第五讲', '机器人感知与行动协同；环境交互与自适应学习', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1085, 11, 4, 25, '人工智能伦理', '第六讲', '第六讲', '数据偏见、算法歧视等伦理问题的分析与应对', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1086, 11, 4, 26, '技术风险', '第六讲', '第六讲', '失业危机、深度伪造、安全漏洞等社会技术风险', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1087, 11, 4, 27, '法律与治理', '第六讲', '第六讲', 'AI监管框架；全球政策对比（欧盟AI法案/中国治理规范/美国标准）', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1088, 11, 4, -1, 'AI在医疗影像诊断的应用', '第五讲', '第五讲', '深度学习在CT/MRI影像分析中的实践案例', 3, 0, '2025-06-28 19:41:54', '2025-06-28 19:41:54');
INSERT INTO `topic_points` VALUES (1089, 11, 4, NULL, ' 统计学习理论', '第二讲', NULL, '核心概念如下：\nVC 维（Vapnik-Chervonenkis Dimension）：衡量模型的 “复杂度”（如线性分类器的 VC 维为特征数 + 1），VC 维越高，模型拟合能力越强，但过拟合风险越高；\n结构风险最小化（SRM）：在 “经验风险（训练误差）” 与 “模型复杂度” 间权衡，避免过拟合（传统经验风险最小化仅关注训练误差，易过拟合）；\n支持向量机（SVM）：基于 SLT 的经典模型，通过 “最大间隔分类超平面” 实现高泛化能力，适用于小样本分类任务。', 3, 0, '2025-08-23 21:04:13', '2025-08-23 21:04:23');
INSERT INTO `topic_points` VALUES (1090, 11, 4, NULL, '计算思维实践模块', '第三讲', NULL, '计算思维实践模块有一下几种：\n问题建模思维：用 “计算模型” 映射现实问题，将模糊需求转化为明确的计算目标。\n例：用 “线性回归模型” 抽象 “房价与面积、地段的关系”，将 “预测房价” 转化为 “求解回归方程参数” 的计算问题。\n数据思维：通过数据采集、分析、处理提取信息，支撑决策。\n例：电商平台通过分析用户 “浏览记录、购买历史、停留时间” 等数据，构建用户画像，实现 “个性化推荐”。\n自动化思维：设计规则或工具，让重复任务自动执行，减少人工干预。\n例：用 Python 脚本自动抓取每日天气数据并生成报表，替代 “手动查询 + 复制粘贴” 的重复工作。\n系统思维：考虑组件间的关联与依赖，设计鲁棒（稳定）的复杂系统。\n例：设计 AI 客服系统时，需协调 “语音识别（转文字）→NLP（理解意图）→知识库（匹配答案）→语音合成（转语音）” 等模块，确保流程连贯、出错时可回溯。\n容错与边界思维：预判问题的异常情况（如数据缺失、操作错误），设计应对方案。\n例：AI 图像识别系统中，对 “模糊图片、无目标图片” 设置 “识别失败提示”，而非崩溃；计算器中对 “除数为 0” 设置报错逻辑。', 3, 0, '2025-08-23 21:07:15', '2025-08-23 21:07:15');
INSERT INTO `topic_points` VALUES (1091, 11, 4, NULL, '经典深度学习网络结构', '第四讲', NULL, '经典深度学习网络结构有一下四种：卷积神经网络、循环神经网络、Transformer、生成式模型', 3, 0, '2025-08-23 21:48:15', '2025-08-23 21:48:15');
INSERT INTO `topic_points` VALUES (1099, 11, 4, NULL, '问题建模思维', '第三章', NULL, '用 “计算模型” 映射现实问题，将模糊需求转化为明确的计算目标。\n例：用 “线性回归模型” 抽象 “房价与面积、地段的关系”，将 “预测房价” 转化为 “求解回归方程参数” 的计算问题。', 4, 0, '2025-08-24 18:34:53', '2025-08-24 18:34:53');
INSERT INTO `topic_points` VALUES (1100, 11, 4, NULL, '数据思维', '计算思维实践模块', NULL, '通过数据采集、分析、处理提取信息，支撑决策。\n例：电商平台通过分析用户 “浏览记录、购买历史、停留时间” 等数据，构建用户画像，实现 “个性化推荐”。', 4, 0, '2025-08-24 18:35:46', '2025-08-24 18:35:46');
