INSERT INTO `topic_templates` VALUES (6, 7, '第五讲人工智能的经典及前沿应用', NULL, '学会专家系统工具及应用；掌握计算机视觉模型和关键技术；学会自然语言处理基本方法；能描述生成式AI的核心原理；能理解\"AI+垂直领域\"创新应用原理。', 2, '2025-06-20 16:57:36', '2025-06-20 16:57:36');
