INSERT INTO `tpa_homework_details` VALUES (1, 17, '[\"12\",\"22\",\"1\"]', NULL, NULL, '数学', ' 空间几何体的结构 ', '单选题', 1, ' 下列说法正确的是（  ） ', ' A ', ' 棱柱的侧棱都互相平行且相等，这是棱柱的基本特征。棱锥的侧棱相交于一点，圆柱上下底面平行，棱台的侧棱延长后相交于一点  ', ' 简单 ', 10, 1, '0.941176470', 34, 32, '2025-04-11 15:28:51', '2025-04-11 15:28:51', '2025-04-11 15:28:51', 1, NULL, ' A. 棱柱的侧棱都相等；B. 棱锥的侧棱都相等；C. 圆柱的母线不互相平行；D. 棱台的侧棱延长后不一定交于一点\n', '[\" 棱柱的侧棱都相等\",\" 棱锥的侧棱都相等\",\" 圆柱的母线不互相平行\",\" 棱台的侧棱延长后不一定交于一点\"]');
INSERT INTO `tpa_homework_details` VALUES (2, 17, NULL, NULL, NULL, '数学', ' 空间几何体的三视图和直观图 ', '单选题', 1, ' 一个几何体的正视图、侧视图和俯视图都相同，这个几何体可能是（  ） ', ' C ', ' 正方体的正视图、侧视图和俯视图都是正方形  ', ' 简单 ', 10, 1, '0.939393939', 33, 31, '2025-04-11 15:28:51', '2025-04-11 15:28:51', '2025-04-11 15:28:51', 1, NULL, ' A. 三棱柱；B. 圆柱；C. 正方体；D. 圆锥\n', '[\" 三棱柱\",\" 圆柱\",\" 正方体\",\" 圆锥\"]');
INSERT INTO `tpa_homework_details` VALUES (3, 17, NULL, NULL, NULL, '数学', ' 空间几何体的表面积与体积 ', '单选题', 1, ' 已知正方体的棱长为\\(a\\)，则正方体的表面积\\(S\\)为（  ） ', ' B ', ' 正方体表面积公式为\\(6\\)倍的一个面的面积，一个面面积是\\(a^2\\)，所以表面积\\(S = 6a^2\\)  ', ' 简单 ', 10, 1, '0.909090909', 33, 30, '2025-04-11 15:28:51', '2025-04-11 15:28:51', '2025-04-11 15:28:51', 1, NULL, ' A. \\(4a^2\\)；B. \\(6a^2\\)；C. \\(8a^2\\)；D. \\(12a^2\\)\n', '[\" \\\\(4a^2\\\\)\",\" \\\\(6a^2\\\\)\",\" \\\\(8a^2\\\\)\",\" \\\\(12a^2\\\\)\"]');
INSERT INTO `tpa_homework_details` VALUES (4, 17, NULL, NULL, NULL, '数学', ' 空间几何体的结构 ', '填空题', 1, ' 圆锥的底面半径为\\(3\\)，母线长为\\(5\\)，则圆锥的高为______。 ', ' 4 ', ' 根据圆锥的高、底面半径和母线构成直角三角形，由勾股定理可得高\\(h=\\sqrt{5^{2}-3^{2}} = 4\\)  ', ' 中等 ', 15, 1, '0.878787878', 33, 29, '2025-04-11 15:28:51', '2025-04-11 15:28:51', '2025-04-11 15:28:51', 1, NULL, ' \n', NULL);
INSERT INTO `tpa_homework_details` VALUES (5, 17, NULL, NULL, NULL, '数学', ' 空间几何体的三视图和直观图 ', '填空题', 1, ' 一个水平放置的三角形的斜二测直观图是一个边长为\\(2\\)的正三角形，则原三角形的面积为______。 ', '2√6 ', ' 根据斜二测画法中直观图与原图面积关系\\(S_{原}=2\\sqrt{2}S_{直}\\)，直观图正三角形面积\\(S_{直}=\\frac{\\sqrt{3}}{4}\\times2^{2}=\\sqrt{3}\\)，所以原三角形面积\\(S_{原}=2\\sqrt{2}\\times\\sqrt{3}=2\\sqrt{6}\\)  ', ' 中等 ', 15, 1, '0.281250000', 32, 9, '2025-04-14 20:22:22', '2025-04-14 20:22:22', '2025-04-14 20:22:22', 1, NULL, ' \n', NULL);
INSERT INTO `tpa_homework_details` VALUES (6, 17, NULL, NULL, NULL, '数学', ' 空间几何体的表面积与体积 ', '简答题', 1, ' 有一个长方体，其长、宽、高分别为\\(3\\)、\\(4\\)、\\(5\\)，求这个长方体的体积和表面积。 ', ' 体积\\(V = 3×4×5 = 60\\)；表面积\\(S = 2×(3×4 + 3×5 + 4×5)=2×(12 + 15 + 20)=94\\) ', ' 长方体体积公式\\(V = abc\\)（\\(a,b,c\\)分别为长、宽、高），表面积公式\\(S = 2(ab + bc + ac)\\)  ', ' 中等 ', 20, 1, '1.000000000', 20, 20, '2025-04-11 15:29:13', '2025-04-11 15:29:13', '2025-04-11 15:29:13', 1, NULL, ' \n', NULL);
INSERT INTO `tpa_homework_details` VALUES (7, 17, NULL, NULL, NULL, '数学', ' 空间几何体的结构、表面积与体积 ', '简答题', 1, ' 一个圆柱的底面半径为\\(2\\)，高为\\(5\\)，求该圆柱的侧面积、表面积和体积。 ', ' 侧面积\\(S_{侧}=2\\pi rh = 2\\pi×2×5 = 20\\pi\\)；表面积\\(S = S_{侧}+2\\pi r^{2}=20\\pi + 2\\pi×2^{2}=20\\pi + 8\\pi = 28\\pi\\)；体积\\(V=\\pi r^{2}h=\\pi×2^{2}×5 = 20\\pi\\) ', ' 圆柱侧面积公式\\(S_{侧}=2\\pi rh\\)，表面积公式\\(S = S_{侧}+2\\pi r^{2}\\)，体积公式\\(V=\\pi r^{2}h\\)  ', ' 中等 ', 20, 1, '1.000000000', 19, 19, '2025-04-11 15:29:13', '2025-04-11 15:29:13', '2025-04-11 15:29:13', 1, NULL, ' \n', NULL);
INSERT INTO `tpa_homework_details` VALUES (8, NULL, NULL, 9, NULL, '数学', ' 空间点、直线、平面之间的位置关系 ', '单选题', 2, ' 空间中两条不重合的直线的位置关系有几种？', 'C ', ' 空间中两条不重合的直线位置关系有相交、平行、异面三种 ', ' 简单 ', 15, 1, '0.966666666', 30, 29, '2025-04-14 11:12:49', '2025-04-14 11:12:49', '2025-04-14 11:12:49', 1, NULL, ' A. 1种；B. 2种；C. 3种；D. 4种\n', '[\" 1种\",\" 2种\",\" 3种\",\" 4种\"]');
INSERT INTO `tpa_homework_details` VALUES (9, NULL, NULL, 9, NULL, '数学', ' 空间点、直线、平面之间的位置关系 ', '单选题', 2, ' 若一条直线与一个平面有且只有一个公共点，则直线与平面的位置关系是？', 'B ', ' 一条直线与一个平面有且只有一个公共点时，直线与平面相交 ', ' 简单 ', 15, 1, '0.966666666', 30, 29, '2025-04-14 11:12:49', '2025-04-14 11:12:49', '2025-04-14 11:12:49', 1, NULL, ' A. 平行；B. 相交；C. 在平面内；D. 不确定\n', '[\" 平行\",\" 相交\",\" 在平面内\",\" 不确定\"]');
INSERT INTO `tpa_homework_details` VALUES (10, NULL, NULL, 9, NULL, '数学', ' 空间点、直线、平面之间的位置关系 ', '填空题', 2, ' 直线\\(a\\)不在平面\\(\\alpha\\)内，直线\\(a\\)与平面\\(\\alpha\\)的位置关系是______。', '平行或相交 ', ' 直线不在平面内，那么直线与平面的位置关系就是平行或相交 ', ' 简单 ', 15, 1, '0.923076923', 26, 24, '2025-04-14 11:12:49', '2025-04-14 11:12:49', '2025-04-14 11:12:49', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (11, NULL, NULL, 9, NULL, '数学', ' 空间点、直线、平面之间的位置关系 ', '单选题', 2, ' 已知直线\\(l\\)，\\(m\\)，平面\\(\\alpha\\)，\\(m\\subset\\alpha\\)，若\\(l\\parallel m\\)，则直线\\(l\\)与平面\\(\\alpha\\)的位置关系是？', 'A ', ' 因为\\(m\\subset\\alpha\\)，\\(l\\parallel m\\)，则\\(l\\)可能平行于\\(\\alpha\\)，也可能\\(l\\subset\\alpha\\) ', ' 中等 ', 20, 1, '0.961538461', 26, 25, '2025-04-14 11:12:49', '2025-04-14 11:12:49', '2025-04-14 11:12:49', 1, NULL, ' A. \\(l\\parallel\\alpha\\)或\\(l\\subset\\alpha\\)；B. \\(l\\parallel\\alpha\\)；C. \\(l\\subset\\alpha\\)；D. \\(l\\)与\\(\\alpha\\)相交\n', '[\" \\\\(l\\\\parallel\\\\alpha\\\\)或\\\\(l\\\\subset\\\\alpha\\\\)\",\" \\\\(l\\\\parallel\\\\alpha\\\\)\",\" \\\\(l\\\\subset\\\\alpha\\\\)\",\" \\\\(l\\\\)与\\\\(\\\\alpha\\\\)相交\"]');
INSERT INTO `tpa_homework_details` VALUES (12, NULL, NULL, 9, NULL, '数学', ' 空间点、直线、平面之间的位置关系 ', '简答题', 2, ' 简述空间中直线与直线的位置关系，并举例说明。', '空间中直线与直线的位置关系有相交、平行、异面。相交如墙角处的三条交线中任意两条相交；平行如黑板的上下两条边所在直线平行；异面如教室的一条侧棱与和它不相交的面对角线异面。 ', '无', ' 中等 ', 15, 1, '1.000000000', 14, 14, '2025-04-14 11:12:57', '2025-04-14 11:12:57', '2025-04-14 11:12:57', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (13, NULL, NULL, 9, NULL, '数学', ' 空间点、直线、平面之间的位置关系 ', '填空题', 2, ' 若直线\\(a\\)与直线\\(b\\)异面，直线\\(b\\)与直线\\(c\\)异面，则直线\\(a\\)与直线\\(c\\)的位置关系是______。', '平行、相交或异面 ', ' 直线\\(a\\)与直线\\(c\\)的位置关系不确定，这三种情况都有可能 ', ' 中等 ', 20, 1, '0.520000000', 25, 13, '2025-04-14 11:12:49', '2025-04-14 11:12:49', '2025-04-14 11:12:49', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (14, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中，两条直线如果不相交且不在同一平面内，它们的位置关系是？', 'C', '空间中，两条直线如果不相交且不在同一平面内，它们的位置关系是异面直线。', '中', 10, 1, '0', 0, 0, '2025-04-08 09:14:45', '2025-04-08 09:11:07', '2025-04-08 09:14:45', 1, NULL, 'A. 平行 B. 相交 C. 异面 D. 重合\n', '[\"\",\"平行\",\"\",\"相交\",\"\",\"异面\",\"\",\"重合\"]');
INSERT INTO `tpa_homework_details` VALUES (15, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定一个平面？', 'A,B,C', '通过三个不共线的点、两条相交的直线、一条直线和直线外的一个点都可以确定一个平面。', '中', 12, 1, '0', 0, 0, '2025-04-05 15:12:29', NULL, NULL, 1, NULL, 'A. 三个不共线的点 B. 两条相交的直线 C. 一条直线和直线外的一个点 D. 两条平行直线\n', '[\"\",\"三个不共线的点\",\"\",\"两条相交的直线\",\"\",\"一条直线和直线外的一个点\",\"\",\"两条平行直线\"]');
INSERT INTO `tpa_homework_details` VALUES (16, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，两条直线如果平行且在同一平面内，它们的位置关系是____。', '平行', '空间中，两条直线如果平行且在同一平面内，它们的位置关系是平行。', '易', 8, 1, '0', 0, 0, '2025-04-05 15:12:34', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (17, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中，一条直线与一个平面相交，且直线与平面内的所有直线都垂直，这条直线与平面的位置关系是？', 'B', '空间中，一条直线与一个平面相交，且直线与平面内的所有直线都垂直，这条直线与平面的位置关系是垂直。', '中', 10, 1, '0', 0, 0, '2025-04-05 15:12:41', NULL, NULL, 1, NULL, 'A. 平行 B. 垂直 C. 斜交 D. 重合\n', '[\"\",\"平行\",\"\",\"垂直\",\"\",\"斜交\",\"\",\"重合\"]');
INSERT INTO `tpa_homework_details` VALUES (18, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定两条直线是异面直线？', 'A,B', '两条直线不相交且不在同一平面内、两条直线不在同一平面内且不平行都可以确定两条直线是异面直线。', '中', 12, 1, '0', 0, 0, '2025-04-05 15:12:46', NULL, NULL, 1, NULL, 'A. 两条直线不相交且不在同一平面内 B. 两条直线不在同一平面内且不平行 C. 两条直线相交 D. 两条直线平行\n', '[\"\",\"两条直线不相交且不在同一平面内\",\"\",\"两条直线不在同一平面内且不平行\",\"\",\"两条直线相交\",\"\",\"两条直线平行\"]');
INSERT INTO `tpa_homework_details` VALUES (19, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，两条直线如果相交且不在同一平面内，它们的位置关系是____。', '相交', '空间中，两条直线如果相交且不在同一平面内，它们的位置关系是相交。', '易', 8, 1, '0', 0, 0, '2025-04-05 15:12:52', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (20, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中，两条直线如果平行且不在同一平面内，它们的位置关系是？', 'A', '空间中，两条直线如果平行且不在同一平面内，它们的位置关系是平行。', '中', 10, 1, '0', 0, 0, '2025-04-05 15:12:58', NULL, NULL, 1, NULL, 'A. 平行 B. 相交 C. 异面 D. 重合\n', '[\"\",\"平行\",\"\",\"相交\",\"\",\"异面\",\"\",\"重合\"]');
INSERT INTO `tpa_homework_details` VALUES (21, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定两条直线是平行直线？', 'A,C', '两条直线在同一平面内且不相交、两条直线不在同一平面内且不相交都可以确定两条直线是平行直线。', '中', 12, 1, '0', 0, 0, '2025-04-05 15:13:04', NULL, NULL, 1, NULL, 'A. 两条直线在同一平面内且不相交 B. 两条直线不在同一平面内且不相交 C. 两条直线在同一平面内且相交 D. 两条直线不在同一平面内且相交\n', '[\"\",\"两条直线在同一平面内且不相交\",\"\",\"两条直线不在同一平面内且不相交\",\"\",\"两条直线在同一平面内且相交\",\"\",\"两条直线不在同一平面内且相交\"]');
