INSERT INTO `tpa_homework_details` VALUES (23, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中，两条直线如果相交且在同一平面内，它们的位置关系是？', 'B', '空间中，两条直线如果相交且在同一平面内，它们的位置关系是相交。', '中', 10, 1, '0', 0, 0, '2025-04-05 15:13:15', NULL, NULL, 1, NULL, 'A. 平行 B. 相交 C. 异面 D. 重合\n', '[\"\",\"平行\",\"\",\"相交\",\"\",\"异面\",\"\",\"重合\"]');
INSERT INTO `tpa_homework_details` VALUES (24, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '选择题', 3, '空间中两个点是否在同一条直线上，可以通过以下哪种方法判断？', 'A', '通过计算两点之间的距离，若距离为零，则两点在同一直线上。', '易', 8, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, 'A. 计算两点距离 B. 计算两点斜率 C. 计算两点中点 D. 计算两点向量\n', '[\"\",\"计算两点距离\",\"\",\"计算两点斜率\",\"\",\"计算两点中点\",\"\",\"计算两点向量\"]');
INSERT INTO `tpa_homework_details` VALUES (25, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，直线与平面的位置关系有____种。', '3', '直线与平面的位置关系有三种：直线在平面内、直线与平面相交、直线与平面平行。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (26, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '选择题', 3, '以下哪种方法可以用来确定一个平面？', 'C', '通过平面的基本性质，如三点确定一个平面。', '易', 8, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, 'A. 计算平面面积 B. 计算平面周长 C. 三点确定平面 D. 计算平面体积\n', '[\"\",\"计算平面面积\",\"\",\"计算平面周长\",\"\",\"三点确定平面\",\"\",\"计算平面体积\"]');
INSERT INTO `tpa_homework_details` VALUES (27, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，直线与平面相交时，交点的个数为____个。', '1', '直线与平面相交时，只有一个交点。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (28, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '选择题', 3, '以下哪种情况表示直线与平面平行？', 'D', '直线与平面没有交点时，表示直线与平面平行。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, 'A. 直线在平面内 B. 直线与平面相交 C. 直线与平面重合 D. 直线与平面没有交点\n', '[\"\",\"直线在平面内\",\"\",\"直线与平面相交\",\"\",\"直线与平面重合\",\"\",\"直线与平面没有交点\"]');
INSERT INTO `tpa_homework_details` VALUES (29, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，直线与平面重合时，直线上的每一点都在____。', '平面内', '直线与平面重合时，直线上的每一点都在平面内。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (30, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '选择题', 3, '以下哪种方法可以用来判断直线与平面的位置关系？', 'B', '通过计算直线与平面的交点数量，可以判断直线与平面的位置关系。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, 'A. 计算直线长度 B. 计算交点数量 C. 计算平面面积 D. 计算平面体积\n', '[\"\",\"计算直线长度\",\"\",\"计算交点数量\",\"\",\"计算平面面积\",\"\",\"计算平面体积\"]');
INSERT INTO `tpa_homework_details` VALUES (31, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，直线与平面平行时，直线上的每一点到平面的距离____。', '相等', '直线与平面平行时，直线上的每一点到平面的距离相等。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (32, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '选择题', 3, '以下哪种情况表示直线在平面内？', 'A', '直线上的每一点都在平面内时，表示直线在平面内。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, 'A. 直线上的每一点都在平面内 B. 直线与平面相交 C. 直线与平面平行 D. 直线与平面没有交点\n', '[\"\",\"直线上的每一点都在平面内\",\"\",\"直线与平面相交\",\"\",\"直线与平面平行\",\"\",\"直线与平面没有交点\"]');
INSERT INTO `tpa_homework_details` VALUES (33, NULL, NULL, 9, 4, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，直线与平面相交时，交点的位置在____。', '直线上', '直线与平面相交时，交点的位置在直线上。', '中', 10, 1, '0', 0, 0, '2025-04-05 16:14:06', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (34, 1, '', NULL, NULL, '数学', '空间点的坐标', '选择题', 1, '点(A(1, - 2, 3))关于(x)轴对称的点的坐标是（ ）', 'A', '关于(x)轴对称的点，横坐标不变，纵坐标和竖坐标变为原来的相反数。所以点(A(1, - 2, 3))关于(x)轴对称的点的坐标是((1, 2, - 3))。', '简单', 5, 1, '0', 0, 0, '2025-04-08 09:24:06', '2025-04-08 09:24:06', '2025-04-08 09:24:06', 1, NULL, 'A. ((1, 2, - 3))；B. ((-1, - 2, - 3))；C. ((1, - 2, - 3))；D. ((-1, 2, 3))', NULL);
INSERT INTO `tpa_homework_details` VALUES (35, 1, '', NULL, NULL, '数学', '空间两点间距离', '填空题', 1, '已知空间两点(M(1, - 1, 2))，(N(3, 3, 4))，则(vert MNvert =)______。', '2√6', '根据空间两点间距离公式(vert MNvert = sqrt{(x_2 - x_1)^{2}+(y_2 - y_1)^{2}+(z_2 - z_1)^{2}})，这里(x_1 = 1)，(y_1 = - 1)，(z_1 = 2)，(x_2 = 3)，(y_2 = 3)，(z_2 = 4)，代入可得(vert MNvert = sqrt{(3 - 1)^{2}+(3 + 1)^{2}+(4 - 2)^{2}} = sqrt{4 + 16 + 4} = 2sqrt{6})。', '简单', 5, 1, '0', 0, 0, '2025-04-14 20:22:10', '2025-04-14 20:22:10', '2025-04-14 20:22:10', 1, NULL, '', NULL);
INSERT INTO `tpa_homework_details` VALUES (36, 1, '', NULL, NULL, '数学', '空间向量的坐标运算', '选择题', 1, '已知(overrightarrow{a}=(1, 2, 3))，(overrightarrow{b}=( - 1, 1, 2))，则(overrightarrow{a}cdotoverrightarrow{b}=)（ ）', 'C', '根据空间向量数量积的坐标运算公式(overrightarrow{a}cdotoverrightarrow{b}=x_1x_2 + y_1y_2 + z_1z_2)，这里(x_1 = 1)，(y_1 = 2)，(z_1 = 3)，(x_2 = - 1)，(y_2 = 1)，(z_2 = 2)，则(overrightarrow{a}cdotoverrightarrow{b}=1\\times(-1)+2\\times1 + 3\\times2=-1 + 2 + 6 = 7)。', '中等', 5, 1, '0', 0, 0, '2025-04-08 09:24:06', '2025-04-08 09:24:06', '2025-04-08 09:24:06', 1, NULL, 'A. 1；B. 2；C. 7；D. 8', NULL);
INSERT INTO `tpa_homework_details` VALUES (37, 1, '', NULL, NULL, '数学', '利用空间直角坐标系证明垂直', '简答题', 1, '在空间直角坐标系中，已知(A(1, 0, 0))，(B(0, 1, 0))，(C(0, 0, 1))，(D(1, 1, 1))，证明：(overrightarrow{AB}perpoverrightarrow{CD})。', '先求出(overrightarrow{AB}=(-1, 1, 0))，(overrightarrow{CD}=(1, 1, 0))，然后计算(overrightarrow{AB}cdotoverrightarrow{CD}=(-1)\\times1 + 1\\times1 + 0\\times0 = 0)，因为(overrightarrow{AB}cdotoverrightarrow{CD}=0)，所以(overrightarrow{AB}perpoverrightarrow{CD})。', '要证明两向量垂直，只需证明它们的数量积为 0。先根据点的坐标求出向量的坐标，再利用向量数量积的坐标运算公式计算数量积。', '较难', 5, 1, '0', 0, 0, '2025-04-08 09:24:06', '2025-04-08 09:24:06', '2025-04-08 09:24:06', 1, NULL, '', NULL);
INSERT INTO `tpa_homework_details` VALUES (38, 1, '', NULL, NULL, '数学', '空间直角坐标系中的轨迹问题', '选择题', 1, '在空间直角坐标系中，到点(A(1, 0, 0))和点(B( - 1, 0, 0))距离相等的点的轨迹是（ ）', 'B', '设动点坐标为(P(x,y,z))，根据空间两点间距离公式，(vert PAvert = sqrt{(x - 1)^{2}+y^{2}+z^{2}})，(vert PBvert = sqrt{(x + 1)^{2}+y^{2}+z^{2}})，因为(vert PAvert=vert PBvert)，则((x - 1)^{2}+y^{2}+z^{2}=(x + 1)^{2}+y^{2}+z^{2})，展开化简得(x = 0)，这表示过线段(AB)中点且与(AB)垂直的平面。', '中等', 5, 1, '0', 0, 0, '2025-04-08 09:24:06', '2025-04-08 09:24:06', '2025-04-08 09:24:06', 1, NULL, 'A. 线段(AB)的中点；B. 过线段(AB)中点且与(AB)垂直的平面；C. 直线(AB)；D. 球面', NULL);
INSERT INTO `tpa_homework_details` VALUES (39, 1, '', NULL, NULL, '数学', '空间向量平行判断', '选择题', 1, '已知(overrightarrow{a}=(2, 4, 6))，(overrightarrow{b}=(1, 2, m))，若(overrightarrow{a} \\parallel \\overrightarrow{b})，则(m)的值为（ ）', '3', '若两向量平行，则对应坐标成比例，即(frac{2}{1}=frac{4}{2}=frac{6}{m})，解得(m = 3)。', '中等', 5, 1, '0', 0, 0, '2025-04-08 09:24:06', '2025-04-08 09:24:06', '2025-04-08 09:24:06', 1, NULL, 'A. 3；B. 4；C. 5；D. 6', NULL);
INSERT INTO `tpa_homework_details` VALUES (40, 1, '', NULL, NULL, '数学', '空间点到平面距离计算', '填空题', 1, '已知点(P(1, 2, 3))，平面(\\alpha)的方程为(2x + 3y - z + 4 = 0)，则点(P)到平面(\\alpha)的距离为______。', '11/√14', '根据点到平面的距离公式(d = \\frac{|Ax_0 + By_0 + Cz_0 + D|}{\\sqrt{A^2 + B^2 + C^2}})，这里(A = 2)，(B = 3)，(C = -1)，(D = 4)，(x_0 = 1)，(y_0 = 2)，(z_0 = 3)，代入可得(d = \\frac{|2×1 + 3×2 - 3 + 4|}{\\sqrt{2^2 + 3^2 + (-1)^2}} = \\frac{11}{\\sqrt{14}})。', '较难', 5, 1, '0', 0, 0, '2025-04-14 20:29:31', '2025-04-14 20:29:31', '2025-04-14 20:29:31', 1, NULL, '', NULL);
INSERT INTO `tpa_homework_details` VALUES (41, 2, '', NULL, NULL, '数学', '直线与圆位置关系判断选择题', '选择题', 1, '已知圆(C: (x - 1)^2 + (y - 2)^2 = 25)，直线(l: 3x + 4y - 15 = 0)，则直线(l)与圆(C)的位置关系是（ ）', '相交', '先求圆心((1, 2))到直线(3x + 4y - 15 = 0)的距离(d)，根据点到直线距离公式(d = frac{|3×1 + 4×2 - 15|}{sqrt{3^2 + 4^2}} = frac{|3 + 8 - 15|}{5} = frac{4}{5} \\u003c 5)（圆半径），所以直线与圆相交。', '中等', 5, 1, '0.666666666', 6, 4, '2025-04-15 14:36:25', '2025-04-15 14:36:25', '2025-04-15 14:36:25', 1, NULL, 'A. 相离；B. 相切；C. 相交；D. 不确定', NULL);
INSERT INTO `tpa_homework_details` VALUES (42, 2, '', NULL, NULL, '数学', '直线与圆相切时的参数值填空题', '填空题', 1, '已知圆(x^2 + y^2 = 4)，直线(y = kx + 2)与圆相切，则(k)的值为______。', '(k = 0)或(k = ±√3})', '根据直线与圆相切时，圆心到直线的距离等于半径。圆(x^2 + y^2 = 4)圆心((0, 0))，半径(r = 2)，由点到直线距离公式(d = frac{|0 - 0 + 2|}{sqrt{k^2 + 1}} = 2)，即(frac{2}{sqrt{k^2 + 1}} = 2)，两边平方得(4 = 4(k^2 + 1))，解得(k = 0)；又因为直线(y = kx + 2)恒过点((0, 2))，此点在圆上，所以过该点的切线斜率为(pmsqrt{3})，综上(k = 0)或(k = pmsqrt{3})。', '较难', 5, 1, '0', 7, 0, '2025-04-15 14:36:39', '2025-04-15 14:36:39', '2025-04-15 14:36:39', 1, NULL, '', NULL);
INSERT INTO `tpa_homework_details` VALUES (43, 2, '', NULL, NULL, '数学', '直线与圆相交弦长简答题', '简答题', 1, '已知圆(C: x^2 + y^2 - 2x - 4y - 20 = 0)，直线(l: 2x - y + 1 = 0)，求直线(l)与圆(C)相交所得弦长。', '弦长为(4sqrt{5})。先将圆方程化为标准方程((x - 1)^2 + (y - 2)^2 = 25)，圆心((1, 2))，半径(r = 5)。根据点到直线距离公式求圆心到直线距离(d = frac{|2×1 - 2 + 1|}{sqrt{2^2 + (-1)^2}} = frac{1}{sqrt{5}})。再根据弦长公式(L = 2sqrt{r^2 - d^2} = 2sqrt{25 - frac{1}{5}} = 4√{5})。', '先将圆方程化为标准方程确定圆心和半径，再求圆心到直线距离，最后利用弦长公式求解。', '中等', 5, 1, '1.000000000', 6, 6, '2025-04-15 14:37:13', '2025-04-15 14:37:13', '2025-04-15 14:37:13', 1, NULL, '', NULL);
INSERT INTO `tpa_homework_details` VALUES (44, 2, '', NULL, NULL, '数学', '过圆外一点求圆的切线方程选择题', '选择题', 1, '过点((3, 1))作圆(x^2 + y^2 = 4)的切线，则切线方程为（ ）', 'x = 3或(4x - 3y - 9 = 0)', '当直线斜率不存在时，(x = 3)与圆相切；当直线斜率存在时，设切线方程(y - 1 = k(x - 3))，即(kx - y - 3k + 1 = 0)，由圆心到直线距离等于半径得(frac{| - 3k + 1|}{sqrt{k^2 + 1}} = 2)，解得(k = frac{4}{3})，切线方程为(4x - 3y - 9 = 0)。所以切线方程为(x = 3)或(4x - 3y - 9 = 0)。', '较难', 5, 1, '0', 7, 0, '2025-04-15 14:36:55', '2025-04-15 14:36:55', '2025-04-15 14:36:55', 1, NULL, 'A. (x = 3)；B. (4x - 3y - 9 = 0)；C. (x = 3)或(4x - 3y - 9 = 0)；D. (4x + 3y - 15 = 0)', NULL);
INSERT INTO `tpa_homework_details` VALUES (45, 2, '', NULL, NULL, '数学', '直线与圆位置关系的应用简答题', '简答题', 1, '已知圆(O: x^2 + y^2 = 1)，直线(l: y = x + b)，若直线(l)与圆(O)有两个不同交点(A)、(B)，求(b)的取值范围。', '-√2<b< √2', '利用直线与圆的位置关系，通过圆心到直线距离与半径的比较来确定参数范围。', '中等', 5, 1, '1.000000000', 6, 6, '2025-04-15 14:37:13', '2025-04-15 14:37:13', '2025-04-15 14:37:13', 1, NULL, '', NULL);
INSERT INTO `tpa_homework_details` VALUES (46, 2, '', NULL, NULL, '数学', '圆的切线性质应用选择题', '选择题', 1, '已知圆(O: x^2 + y^2 = 9)，过点(A(1, 2))作圆的切线，切点为(B)，则(\\vert AB\\vert)的值为（ ）', '2√2', '连接(OA)，(OB)，由圆的切线性质知(OB \\perp AB)。先求(\\vert OA\\vert = \\sqrt{1^2 + 2^2} = \\sqrt{5})，圆半径(\\vert OB\\vert = 3)，根据勾股定理(\\vert AB\\vert = \\sqrt{\\vert OA\\vert^2 - \\vert OB\\vert^2} = \\sqrt{5 - 9} = 2\\sqrt{2})。', '中等', 5, 1, '0', 5, 0, '2025-04-15 14:37:07', '2025-04-15 14:37:07', '2025-04-15 14:37:07', 1, NULL, 'A. \\sqrt{5}；B. 2\\sqrt{2}；C. 3；D. \\sqrt{10}', NULL);
INSERT INTO `tpa_homework_details` VALUES (47, 2, '', NULL, NULL, '数学', '直线与圆相交时弦中点轨迹方程简答题', '简答题', 1, '已知圆(C: x^2 + y^2 = 16)，直线(l: y = x + b)与圆(C)相交于(A)、(B)两点，求弦(AB)中点的轨迹方程。', '设弦(AB)中点为(M(x,y))，圆心(C(0,0))。因为(CM垂直 AB)，(k_{AB} = 1)，则(k_{CM} = -1)，即(y/x= -1)，整理得(y = -x)  。又因为点(M)在圆内，联立(y = -x)与(x^2 + y^2 = 16)得(2x^2 = 16)，解得(x = ±2√2)，所以弦(AB)中点的轨迹方程为(y = -x(-2√2<x<2√2)。', '利用直线与圆的位置关系，结合垂径定理，通过中点与圆心连线和直线垂直的斜率关系来求轨迹方程。注意中点在圆内，需确定(x)的取值范围。', '较难', 5, 1, '0', 0, 0, '2025-04-14 20:52:11', '2025-04-14 20:52:11', '2025-04-14 20:52:11', 1, NULL, '', NULL);
INSERT INTO `tpa_homework_details` VALUES (48, 23, NULL, NULL, NULL, '数学', '空间点、直线、平面之间的位置关系', '选择题', 1, '若一条直线与一个平面有两个公共点，则直线与平面的位置关系是（  ）', 'A', '一条直线与一个平面有两个公共点，根据直线与平面的位置关系定义，直线就在这个平面内。', '简单', 15, 1, '0', 0, 0, '2025-04-11 12:03:11', '2025-04-11 12:03:11', '2025-04-11 12:03:11', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (49, 23, NULL, NULL, NULL, '数学', '空间点、直线、平面之间的位置关系', '填空题', 1, '不共面的四点可以确定____个平面。', '4', '不共面的四点中任意三个点可确定一个平面，从四个点中选三个点的组合数为\\(C_{4}^3 = 4\\)，所以可以确定4个平面。', '简单', 15, 1, '0', 0, 0, '2025-04-11 12:03:11', '2025-04-11 12:03:11', '2025-04-11 12:03:11', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (50, 23, NULL, NULL, NULL, '数学', '直线、平面平行的判定及其性质', '选择题', 1, '若平面\\(\\alpha\\)内有无数条直线与平面\\(\\beta\\)平行，则\\(\\alpha\\)与\\(\\beta\\)的位置关系是（  ）', 'D', '平面\\(\\alpha\\)内有无数条直线与平面\\(\\beta\\)平行，当这无数条直线互相平行时，平面\\(\\alpha\\)与平面\\(\\beta\\)可能相交，也可能平行。', '中等', 20, 1, '0', 0, 0, '2025-04-12 11:09:44', '2025-04-12 11:09:44', '2025-04-12 11:09:44', 1, NULL, 'A. 平行  B. 相交  C. 异面  D. 平行或相交\n', '[\"平行\",\"\",\"相交\",\"\",\"异面\",\"\",\"平行或相交\"]');
INSERT INTO `tpa_homework_details` VALUES (51, 23, NULL, NULL, NULL, '数学', '直线、平面平行的判定及其性质', '填空题', 1, '若直线\\(a\\parallel\\)平面\\(\\alpha\\)，直线\\(a\\subset\\)平面\\(\\beta\\)，\\(\\alpha\\cap\\beta = b\\)，则\\(a\\)与\\(b\\)的位置关系是____。', '平行', '根据直线与平面平行的性质定理，如果一条直线和一个平面平行，经过这条直线的平面和这个平面相交，那么这条直线和交线平行。所以\\(a\\parallel b\\)。', '中等', 20, 1, '0', 0, 0, '2025-04-11 12:03:11', '2025-04-11 12:03:11', '2025-04-11 12:03:11', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (52, 23, NULL, NULL, NULL, '数学', '直线、平面平行的判定及其性质', '选择题', 1, '下列条件中，能判断两个平面平行的是（  ）', 'C', 'A选项，一个平面内有无数条直线平行于另一个平面，这无数条直线如果互相平行，两个平面可能相交；B选项，一个平面内有两条直线平行于另一个平面，这两条直线如果不相交，不能判定两平面平行；D选项，两个平面同时垂直于一条直线，只能说明这两个平面平行或重合；C选项，一个平面内有两条相交直线都平行于另一个平面，符合平面与平面平行的判定定理。', '中等', 15, 1, '0', 0, 0, '2025-04-11 12:03:11', '2025-04-11 12:03:11', '2025-04-11 12:03:11', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (53, 23, NULL, NULL, NULL, '数学', '直线、平面平行的判定及其性质', '填空题', 1, '已知直线\\(m\\)，\\(n\\)，平面\\(\\alpha\\)，\\(\\beta\\)，若\\(m\\parallel n\\)，\\(m\\parallel\\alpha\\)，\\(n\\not\\subset\\alpha\\)，则\\(n\\)与\\(\\alpha\\)的位置关系是____。', '\\(n\\parallel\\alpha\\)', '因为\\(m\\parallel n\\)，\\(m\\parallel\\alpha\\)，\\(n\\not\\subset\\alpha\\)，根据直线与平面平行的判定定理，如果平面外一条直线和这个平面内的一条直线平行，那么这条直线和这个平面平行，所以\\(n\\parallel\\alpha\\) 。', '中等', 15, 1, '0', 0, 0, '2025-04-11 12:03:11', '2025-04-11 12:03:11', '2025-04-11 12:03:11', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (54, NULL, NULL, 16, NULL, '数学', '直线斜率的计算', '单选题', 2, '已知直线上两点\\(A(1,2)\\)，\\(B(3,4)\\)，则直线\\(AB\\)的斜率为（  ）', 'B', '根据过两点\\((x_1,y_1)\\)，\\((x_2,y_2)\\)直线的斜率公式\\(k=\\frac{y_2 - y_1}{x_2 - x_1}\\)，这里\\(x_1 = 1\\)，\\(y_1 = 2\\)，\\(x_2 = 3\\)，\\(y_2 = 4\\)，则\\(k=\\frac{4 - 2}{3 - 1}=\\frac{2}{2}=1\\)。', '易', 5, 1, '0', 0, 0, '2025-04-12 15:03:14', '2025-04-12 15:03:14', '2025-04-12 15:03:15', 1, NULL, 'A. (0)  B. (1)  C. (2)  D. (3)\n', '[\" (0)\",\" (1)\",\" (2)\",\" (3)\"]');
INSERT INTO `tpa_homework_details` VALUES (55, NULL, NULL, 16, NULL, '数学', '直线斜率与倾斜角大小比较', '单选题', 2, '已知直线\\(l_1\\)的倾斜角\\(\\alpha_1 = 30^{\\circ}\\)，直线\\(l_2\\)的斜率\\(k_2 = 1\\)，则\\(\\alpha_1\\)与\\(\\alpha_2\\)（\\(\\alpha_2\\)为\\(l_2\\)倾斜角）的大小关系是（  ）', 'A', '因为\\(k_2 = 1\\)，由\\(k = \\tan\\alpha\\)可得\\(\\tan\\alpha_2 = 1\\)，则\\(\\alpha_2 = 45^{\\circ}\\)，而\\(\\alpha_1 = 30^{\\circ}\\)，所以\\(\\alpha_1\\lt\\alpha_2\\) 。', '中', 6, 1, '0', 0, 0, '2025-04-12 15:03:14', '2025-04-12 15:03:14', '2025-04-12 15:03:15', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (56, NULL, NULL, 16, NULL, '数学', '直线倾斜角的概念', '填空题', 2, '直线\\(l\\)向上的方向与\\(x\\)轴正方向所成的最小正角叫做直线\\(l\\)的____。', '倾斜角', '根据直线倾斜角的定义，直线\\(l\\)向上的方向与\\(x\\)轴正方向所成的最小正角就是倾斜角。', '易', 3, 1, '0', 0, 0, '2025-04-12 15:03:14', '2025-04-12 15:03:14', '2025-04-12 15:03:15', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (57, NULL, NULL, 16, NULL, '数学', '倾斜角与斜率的关系', '填空题', 2, '当直线倾斜角\\(\\alpha\\neq90^{\\circ}\\)时，直线的斜率\\(k\\)与倾斜角\\(\\alpha\\)的关系是____。', ' \\(k = \\tan\\alpha\\) ', '这是倾斜角与斜率关系的基本公式，当倾斜角不是\\(90^{\\circ}\\)时，斜率就等于倾斜角的正切值。', '中', 6, 1, '0', 0, 0, '2025-04-12 15:03:14', '2025-04-12 15:03:14', '2025-04-12 15:03:15', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (58, NULL, NULL, 17, NULL, '数学', '空间点与直线的位置关系', '单选题', 2, '空间中一点与一条直线的位置关系有几种？修改过的', '2种', '空间中一点与一条直线的位置关系有两种，即点在直线上和点在直线外。', '易', 10, 1, '0', 0, 0, '2025-04-12 15:24:47', '2025-04-12 15:24:47', '2025-04-12 15:24:47', 1, NULL, 'A. 1种  B. 2种  C. 3种  D. 4种\n', '[\" 1种\",\" 2种\",\" 3种\",\" 4种\"]');
INSERT INTO `tpa_homework_details` VALUES (59, NULL, NULL, 17, NULL, '数学', '空间直线与直线的位置关系', '单选题', 2, '在空间中，两条异面直线所成角的范围是？', '（0，90°]', '异面直线所成角的范围是（0，90°] ，这是异面直线所成角的定义规定。', '易', 10, 1, '0', 0, 0, '2025-04-12 15:24:47', '2025-04-12 15:24:47', '2025-04-12 15:24:47', 1, NULL, 'A. [0，90°]  B. （0，90°]  C. [0，180°]  D. （0，180°）\n', '[\" [0，90°]\",\" （0，90°]\",\" [0，180°]\",\" （0，180°）\"]');
INSERT INTO `tpa_homework_details` VALUES (60, NULL, NULL, 17, NULL, '数学', '空间直线与平面的位置关系', '单选题', 2, '若一条直线与一个平面没有公共点，则这条直线与该平面的关系是？', '平行', '直线与平面没有公共点，根据定义就是直线与平面平行。', '易', 10, 1, '0', 0, 0, '2025-04-12 15:24:47', '2025-04-12 15:24:47', '2025-04-12 15:24:47', 1, NULL, 'A. 相交  B. 平行  C. 直线在平面内  D. 不确定\n', '[\" 相交\",\" 平行\",\" 直线在平面内\",\" 不确定\"]');
INSERT INTO `tpa_homework_details` VALUES (61, NULL, NULL, 17, NULL, '数学', '空间平面与平面的位置关系', '简答题', 2, '简述空间中两个平面的位置关系有哪些？', '两个平面的位置关系有平行和相交两种。平行是指两个平面没有公共点；相交是指两个平面有一条公共直线。', '空间中平面与平面只有这两种不同的位置关系，根据定义来判断和区分。', '中', 15, 1, '0', 0, 0, '2025-04-12 15:24:47', '2025-04-12 15:24:47', '2025-04-12 15:24:47', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (62, NULL, NULL, 17, NULL, '数学', '综合位置关系', '简答题', 2, '已知直线a在平面α内，直线b与平面α相交，直线b与直线a异面，若直线c与直线b平行，那么直线c与平面α有怎样的位置关系？', '直线c与平面α相交。因为直线b与平面α相交，直线c与直线b平行，根据直线与平面位置关系的判定，如果一条直线和一个平面相交，另一条直线和这条直线平行，那么另一条直线也和这个平面相交。', '综合考查多种位置关系的知识点，通过已知条件逐步推理得出结论。', '中', 15, 1, '0', 0, 0, '2025-04-12 15:24:47', '2025-04-12 15:24:47', '2025-04-12 15:24:47', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (63, NULL, NULL, 18, NULL, '数学', '空间几何体的结构特征', '单选题', 2, '下列几何体中，有一个面是三角形，其余各面都是有一个公共顶点的三角形的是（  ）', 'A', '棱锥的定义就是有一个面是多边形，其余各面都是有一个公共顶点的三角形，所以该几何体是棱锥。', '易', 15, 1, '0', 0, 0, '2025-04-13 00:26:21', '2025-04-13 00:26:21', '2025-04-13 00:26:22', 1, NULL, 'A. 棱锥  B. 棱柱  C. 圆柱  D. 圆锥\n', '[\" 棱锥\",\" 棱柱\",\" 圆柱\",\" 圆锥\"]');
INSERT INTO `tpa_homework_details` VALUES (64, NULL, NULL, 18, NULL, '数学', '圆柱的结构特征', '单选题', 2, '圆柱的母线与底面的位置关系是（  ）', 'C', '圆柱的母线是垂直于底面的，这是圆柱的基本结构特征。', '中', 25, 1, '0', 0, 0, '2025-04-13 00:26:21', '2025-04-13 00:26:21', '2025-04-13 00:26:22', 1, NULL, 'A. 平行  B. 相交  C. 垂直  D. 不确定\n', '[\" 平行\",\" 相交\",\" 垂直\",\" 不确定\"]');
INSERT INTO `tpa_homework_details` VALUES (65, NULL, NULL, 18, NULL, '数学', '空间几何体的分类', '多选题', 2, '以下哪些属于旋转体（  ）', 'ACD', '圆柱、圆锥、球是分别由矩形、直角三角形、半圆绕着一条轴旋转得到的，属于旋转体，而棱柱是多面体，不是旋转体。', '易', 20, 1, '0', 0, 0, '2025-04-13 00:26:21', '2025-04-13 00:26:21', '2025-04-13 00:26:22', 1, NULL, 'A. 圆柱  B. 棱柱  C. 圆锥  D. 球\n', '[\" 圆柱\",\" 棱柱\",\" 圆锥\",\" 球\"]');
INSERT INTO `tpa_homework_details` VALUES (66, NULL, NULL, 18, NULL, '数学', '棱柱的结构特征', '填空题', 2, '棱柱的侧面都是__________。', '平行四边形', '根据棱柱的定义，棱柱的侧面都是平行四边形。', '易', 15, 1, '0', 0, 0, '2025-04-13 00:26:21', '2025-04-13 00:26:21', '2025-04-13 00:26:22', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (67, NULL, NULL, 18, NULL, '数学', '棱台的结构特征', '简答题', 2, '简述棱台的定义及结构特征。', '定义：用一个平行于棱锥底面的平面去截棱锥，底面与截面之间的部分叫做棱台。结构特征：棱台的上下底面是相似多边形，侧面是梯形，侧棱延长后交于一点。', '解析：棱台是由棱锥截得的，根据其形成过程可知其定义和结构特点。', '中', 25, 1, '0', 0, 0, '2025-04-13 00:26:21', '2025-04-13 00:26:21', '2025-04-13 00:26:22', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (68, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '单选题', 3, '空间中两条不重合的直线的位置关系有几种？', 'C', '空间中两条不重合的直线位置关系有相交、平行、异面三种。', '易', 10, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, 'A. 1种  B. 2种  C. 3种  D. 4种\n', '[\" 1种\",\" 2种\",\" 3种\",\" 4种\"]');
INSERT INTO `tpa_homework_details` VALUES (69, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定一个平面？', 'A,B,C', '两条平行线、两条相交线、一条直线和直线外一点都可以确定一个平面。', '中', 15, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, 'A. 两条平行线  B. 两条相交线  C. 一条直线和直线外一点  D. 两条异面直线\n', '[\" 两条平行线\",\" 两条相交线\",\" 一条直线和直线外一点\",\" 两条异面直线\"]');
INSERT INTO `tpa_homework_details` VALUES (70, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '填空题', 3, '平面和直线的垂直关系可以通过____来判定。', '法向量', '平面和直线的垂直关系可以通过法向量来判定。', '易', 10, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (71, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '单选题', 3, '以下哪种情况不属于平面和直线的位置关系？', 'D', '平面和直线的位置关系包括平行、相交、垂直，而不包括异面。', '中', 10, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, 'A. 平行  B. 相交  C. 垂直  D. 异面\n', '[\" 平行\",\" 相交\",\" 垂直\",\" 异面\"]');
INSERT INTO `tpa_homework_details` VALUES (72, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定两条直线平行？', 'A,B', '两条直线的方向向量相同或成比例，可以确定两条直线平行。', '中', 15, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, 'A. 方向向量相同  B. 方向向量成比例  C. 方向向量垂直  D. 方向向量异面\n', '[\" 方向向量相同\",\" 方向向量成比例\",\" 方向向量垂直\",\" 方向向量异面\"]');
INSERT INTO `tpa_homework_details` VALUES (73, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '填空题', 3, '两条异面直线的位置关系可以通过____来判定。', '方向向量', '两条异面直线的位置关系可以通过方向向量来判定。', '中', 10, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (74, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '单选题', 3, '以下哪种情况可以确定平面和直线垂直？', 'C', '平面和直线垂直可以通过平面的法向量与直线的方向向量垂直来判定。', '中', 10, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, 'A. 方向向量相同  B. 方向向量成比例  C. 方向向量垂直  D. 方向向量异面\n', '[\" 方向向量相同\",\" 方向向量成比例\",\" 方向向量垂直\",\" 方向向量异面\"]');
INSERT INTO `tpa_homework_details` VALUES (75, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定平面和平面的位置关系？', 'A,B,C', '平面和平面的位置关系包括平行、相交、垂直。', '中', 15, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, 'A. 平行  B. 相交  C. 垂直  D. 异面\n', '[\" 平行\",\" 相交\",\" 垂直\",\" 异面\"]');
INSERT INTO `tpa_homework_details` VALUES (76, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '填空题', 3, '平面和平面的垂直关系可以通过____来判定。', '法向量', '平面和平面的垂直关系可以通过法向量来判定。', '中', 10, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (77, NULL, NULL, 9, 2, '个性化补充题', '点、直线、平面之间的位置关系', '单选题', 3, '以下哪种情况不属于平面和平面的位置关系？', 'D', '平面和平面的位置关系包括平行、相交、垂直，而不包括异面。', '中', 10, 1, '0', 0, 0, '2025-04-14 11:29:07', NULL, NULL, 1, NULL, 'A. 平行  B. 相交  C. 垂直  D. 异面\n', '[\" 平行\",\" 相交\",\" 垂直\",\" 异面\"]');
INSERT INTO `tpa_homework_details` VALUES (88, NULL, NULL, 9, 3, '个性化补充题', '空间点与平面的位置关系', '单选题', 3, '点A(1,2,3)与平面x+y+z=6的位置关系是？', 'B', '将点A的坐标代入平面方程，得到1+2+3=6，等于平面方程的常数项，因此点A在平面上。', '易', 8, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (89, NULL, NULL, 9, 3, '个性化补充题', '直线与平面的位置关系', '多选题', 3, '直线L: x=1+t, y=2+t, z=3+t与平面x+y+z=6的位置关系是？', 'A, B', '将直线方程代入平面方程，得到1+t+2+t+3+t=6，化简为3t+6=6，解得t=0，因此直线与平面相交于一点。', '中', 12, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, 'A. 相交 B. 有一个交点 C. 平行 D. 重合\n', '[\" 相交\",\" 有一个交点\",\" 平行\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (90, NULL, NULL, 9, 3, '个性化补充题', '空间点与直线的位置关系', '填空题', 3, '点B(2,3,4)到直线L: x=1+t, y=2+t, z=3+t的距离是____。', '√3', '使用点到直线的距离公式计算，得到距离为√3。', '中', 10, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (91, NULL, NULL, 9, 3, '个性化补充题', '平面与平面的位置关系', '单选题', 3, '平面x+y+z=6与平面2x+2y+2z=12的位置关系是？', 'D', '两个平面的法向量相同，且常数项成比例，因此两个平面重合。', '易', 8, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, 'A. 相交 B. 平行 C. 垂直 D. 重合\n', '[\" 相交\",\" 平行\",\" 垂直\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (92, NULL, NULL, 9, 3, '个性化补充题', '空间点与平面的位置关系', '多选题', 3, '点C(0,0,0)与平面x+y+z=6的位置关系是？', 'A', '将点C的坐标代入平面方程，得到0+0+0=0，不等于平面方程的常数项，因此点C在平面外。', '易', 8, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (93, NULL, NULL, 9, 3, '个性化补充题', '直线与平面的位置关系', '填空题', 3, '直线L: x=1+t, y=2+t, z=3+t与平面x+y+z=6的交点是____。', '(1,2,3)', '将直线方程代入平面方程，解得t=0，代入直线方程得到交点(1,2,3)。', '中', 10, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (94, NULL, NULL, 9, 3, '个性化补充题', '空间点与直线的位置关系', '单选题', 3, '点D(1,1,1)到直线L: x=1+t, y=2+t, z=3+t的距离是____。', '√2', '使用点到直线的距离公式计算，得到距离为√2。', '中', 10, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (95, NULL, NULL, 9, 3, '个性化补充题', '平面与平面的位置关系', '多选题', 3, '平面x+y+z=6与平面x+y+z=12的位置关系是？', 'B', '两个平面的法向量相同，但常数项不成比例，因此两个平面平行。', '中', 12, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, 'A. 相交 B. 平行 C. 垂直 D. 重合\n', '[\" 相交\",\" 平行\",\" 垂直\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (96, NULL, NULL, 9, 3, '个性化补充题', '空间点与平面的位置关系', '填空题', 3, '点E(2,2,2)与平面x+y+z=6的位置关系是____。', '在平面内', '将点E的坐标代入平面方程，得到2+2+2=6，等于平面方程的常数项，因此点E在平面内。', '易', 8, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (97, NULL, NULL, 9, 3, '个性化补充题', '直线与平面的位置关系', '单选题', 3, '直线L: x=1+t, y=2+t, z=3+t与平面x+y+z=12的位置关系是？', 'B', '将直线方程代入平面方程，得到1+t+2+t+3+t=12，化简为3t+6=12，解得t=2，因此直线与平面相交于一点。', '中', 12, 1, '0', 0, 0, '2025-04-14 12:08:05', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (108, NULL, NULL, 9, 6, '个性化补充题', '直线的斜率', '单选题', 3, '直线 y = 2x + 3 的斜率是多少？', 'A', '直线的一般式为 y = kx + b，其中 k 为斜率。', '易', 10, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, 'A. 2  B. 3  C. -2  D. -3\n', '[\" 2\",\" 3\",\" -2\",\" -3\"]');
INSERT INTO `tpa_homework_details` VALUES (109, NULL, NULL, 9, 6, '个性化补充题', '直线的截距', '多选题', 3, '直线 y = -x + 5 的截距有哪些？', 'A, B', '直线的一般式为 y = kx + b，其中 b 为 y 截距，x 截距为 -b/k。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, 'A. y 截距为 5  B. x 截距为 5  C. y 截距为 -5  D. x 截距为 -5\n', '[\" y 截距为 5\",\" x 截距为 5\",\" y 截距为 -5\",\" x 截距为 -5\"]');
INSERT INTO `tpa_homework_details` VALUES (110, NULL, NULL, 9, 6, '个性化补充题', '直线的方程', '填空题', 3, '已知直线经过点 (1, 2) 且斜率为 3，求直线方程。', 'y = 3x - 1', '利用点斜式 y - y1 = k(x - x1) 求解。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (111, NULL, NULL, 9, 6, '个性化补充题', '直线的平行', '单选题', 3, '直线 y = 4x + 2 与哪条直线平行？', 'B', '平行直线的斜率相同。', '易', 10, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, 'A. y = 2x + 4  B. y = 4x - 3  C. y = -4x + 2  D. y = 3x + 4\n', '[\" y \\u003d 2x + 4\",\" y \\u003d 4x - 3\",\" y \\u003d -4x + 2\",\" y \\u003d 3x + 4\"]');
INSERT INTO `tpa_homework_details` VALUES (112, NULL, NULL, 9, 6, '个性化补充题', '直线的垂直', '多选题', 3, '直线 y = -2x + 1 与哪些直线垂直？', 'C, D', '垂直直线的斜率乘积为 -1。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, 'A. y = 2x + 3  B. y = -2x + 4  C. y = 0.5x + 2  D. y = 0.5x - 1\n', '[\" y \\u003d 2x + 3\",\" y \\u003d -2x + 4\",\" y \\u003d 0.5x + 2\",\" y \\u003d 0.5x - 1\"]');
INSERT INTO `tpa_homework_details` VALUES (113, NULL, NULL, 9, 6, '个性化补充题', '直线的交点', '填空题', 3, '求直线 y = 2x + 1 和 y = -x + 4 的交点坐标。', '(1, 3)', '解方程组 y = 2x + 1 和 y = -x + 4。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (114, NULL, NULL, 9, 6, '个性化补充题', '直线的倾斜角', '单选题', 3, '直线 y = x + 2 的倾斜角是多少？', 'A', '倾斜角 θ 满足 tanθ = k。', '易', 10, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, 'A. 45°  B. 30°  C. 60°  D. 90°\n', '[\" 45°\",\" 30°\",\" 60°\",\" 90°\"]');
INSERT INTO `tpa_homework_details` VALUES (115, NULL, NULL, 9, 6, '个性化补充题', '直线的位置关系', '多选题', 3, '直线 y = 3x + 2 和 y = 3x - 4 的位置关系是？', 'A, C', '两条直线的斜率相同且截距不同，因此平行且不重合。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, 'A. 平行  B. 重合  C. 不重合  D. 垂直\n', '[\" 平行\",\" 重合\",\" 不重合\",\" 垂直\"]');
INSERT INTO `tpa_homework_details` VALUES (116, NULL, NULL, 9, 6, '个性化补充题', '直线的对称性', '填空题', 3, '直线 y = -x + 3 关于 y 轴对称的直线方程是什么？', 'y = x + 3', '关于 y 轴对称，x 变为 -x。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (117, NULL, NULL, 9, 6, '个性化补充题', '直线的距离', '单选题', 3, '点 (2, 3) 到直线 y = x + 1 的距离是多少？', 'B', '利用点到直线的距离公式计算。', '难', 20, 1, '0', 0, 0, '2025-04-14 12:41:15', NULL, NULL, 1, NULL, 'A. √2  B. √2/2  C. 2  D. 1\n', '[\" √2\",\" √2/2\",\" 2\",\" 1\"]');
INSERT INTO `tpa_homework_details` VALUES (118, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '在空间中，两条直线如果既不相交也不平行，那么它们的关系是？', 'C', '在空间中，两条直线如果既不相交也不平行，那么它们是异面直线。', '中', 10, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, 'A. 相交 B. 平行 C. 异面 D. 重合\n', '[\" 相交\",\" 平行\",\" 异面\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (119, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定一个平面？', 'A,B,C', '三个不共线的点可以确定一个平面，一条直线和直线外一点可以确定一个平面，两条相交直线可以确定一个平面。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, 'A. 三个不共线的点 B. 一条直线和直线外一点 C. 两条相交直线 D. 两条平行直线\n', '[\" 三个不共线的点\",\" 一条直线和直线外一点\",\" 两条相交直线\",\" 两条平行直线\"]');
INSERT INTO `tpa_homework_details` VALUES (120, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，两条直线如果平行且在同一平面内，那么它们的关系是____。', '共面直线', '两条直线如果平行且在同一平面内，那么它们是共面直线。', '易', 5, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (121, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '在空间中，两条直线如果相交，那么它们的关系是？', 'A', '在空间中，两条直线如果相交，那么它们是共面直线。', '易', 10, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, 'A. 共面 B. 异面 C. 平行 D. 重合\n', '[\" 共面\",\" 异面\",\" 平行\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (122, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定一条直线？', 'A,B', '两个不重合的点可以确定一条直线，一条直线和直线外一点可以确定一条直线。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, 'A. 两个不重合的点 B. 一条直线和直线外一点 C. 两条平行直线 D. 两条相交直线\n', '[\" 两个不重合的点\",\" 一条直线和直线外一点\",\" 两条平行直线\",\" 两条相交直线\"]');
INSERT INTO `tpa_homework_details` VALUES (123, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，两条直线如果平行且不在同一平面内，那么它们的关系是____。', '异面直线', '两条直线如果平行且不在同一平面内，那么它们是异面直线。', '中', 10, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (124, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '在空间中，两条直线如果重合，那么它们的关系是？', 'D', '在空间中，两条直线如果重合，那么它们是同一条直线。', '易', 10, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, 'A. 相交 B. 平行 C. 异面 D. 重合\n', '[\" 相交\",\" 平行\",\" 异面\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (125, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定一个点？', 'A,B', '两条相交直线可以确定一个点，一条直线和直线外一点可以确定一个点。', '中', 15, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, 'A. 两条相交直线 B. 一条直线和直线外一点 C. 两条平行直线 D. 两条异面直线\n', '[\" 两条相交直线\",\" 一条直线和直线外一点\",\" 两条平行直线\",\" 两条异面直线\"]');
INSERT INTO `tpa_homework_details` VALUES (126, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中，两条直线如果相交且不在同一平面内，那么它们的关系是____。', '异面直线', '两条直线如果相交且不在同一平面内，那么它们是异面直线。', '中', 10, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (127, NULL, NULL, 9, 7, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '在空间中，两条直线如果平行且在同一平面内，那么它们的关系是？', 'B', '在空间中，两条直线如果平行且在同一平面内，那么它们是共面直线。', '易', 10, 1, '0', 0, 0, '2025-04-14 12:45:56', NULL, NULL, 1, NULL, 'A. 相交 B. 共面 C. 异面 D. 重合\n', '[\" 相交\",\" 共面\",\" 异面\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (128, NULL, NULL, 9, 8, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中两条不重合的直线位置关系有____、____、____三种。', '相交、平行、异面', '空间中两条不重合的直线位置关系有相交、平行、异面三种。', '易', 10, 1, '0', 0, 0, '2025-04-14 19:55:12', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (129, NULL, NULL, 9, 8, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '以下哪种情况不属于空间中两条不重合的直线位置关系？', 'D', '空间中两条不重合的直线位置关系有相交、平行、异面三种，重合不属于其中。', '易', 10, 1, '0', 0, 0, '2025-04-14 19:55:12', NULL, NULL, 1, NULL, 'A. 相交 B. 平行 C. 异面 D. 重合\n', '[\" 相交\",\" 平行\",\" 异面\",\" 重合\"]');
