INSERT INTO `tpa_homework_details` VALUES (170, NULL, NULL, 9, 12, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中两条直线如果既不相交也不平行，那么它们的位置关系是____。', '异面', '空间中两条直线如果既不相交也不平行，那么它们是异面直线。', '易', 8, 1, '0', 0, 0, '2025-04-14 20:15:41', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (171, NULL, NULL, 9, 12, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中一条直线和一个平面如果有一个公共点，那么它们的位置关系是？', 'B', '空间中一条直线和一个平面如果有一个公共点，那么它们相交。', '易', 10, 1, '0', 0, 0, '2025-04-14 20:15:41', NULL, NULL, 1, NULL, 'A. 平行 B. 相交 C. 垂直 D. 重合\n', '[\" 平行\",\" 相交\",\" 垂直\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (172, NULL, NULL, 9, 12, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些情况可以确定两条直线是平行的？', 'A,B', '两条直线在同一平面内且不相交，或者两条直线都与第三条直线平行，可以确定它们平行。', '中', 12, 1, '0', 0, 0, '2025-04-14 20:15:41', NULL, NULL, 1, NULL, 'A. 两条直线在同一平面内且不相交 B. 两条直线都与第三条直线平行 C. 两条直线在不同平面内 D. 两条直线相交\n', '[\" 两条直线在同一平面内且不相交\",\" 两条直线都与第三条直线平行\",\" 两条直线在不同平面内\",\" 两条直线相交\"]');
INSERT INTO `tpa_homework_details` VALUES (173, NULL, NULL, 9, 12, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中两条直线如果既不相交也不平行，那么它们的位置关系是____。', '异面', '空间中两条直线如果既不相交也不平行，那么它们是异面直线。', '易', 8, 1, '0', 0, 0, '2025-04-14 20:15:41', NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (174, NULL, NULL, 9, 12, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中一条直线和一个平面如果没有公共点，那么它们的位置关系是？', 'A', '空间中一条直线和一个平面如果没有公共点，那么它们平行。', '易', 10, 1, '0', 0, 0, '2025-04-14 20:15:41', NULL, NULL, 1, NULL, 'A. 平行 B. 相交 C. 垂直 D. 重合\n', '[\" 平行\",\" 相交\",\" 垂直\",\" 重合\"]');
