INSERT INTO `tpa_homework_details` VALUES (177, NULL, NULL, 9, 12, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中两条直线如果不在同一平面内，且不相交，那么它们的位置关系是？', 'C', '空间中两条直线如果不在同一平面内，且不相交，那么它们是异面直线。', '易', 10, 1, '0', 0, 0, '2025-04-14 20:15:41', NULL, NULL, 1, NULL, 'A. 平行 B. 相交 C. 异面 D. 重合\n```', '[\" 平行\",\" 相交\",\" 异面\"]');
INSERT INTO `tpa_homework_details` VALUES (178, NULL, NULL, 20, NULL, '数学', '空间点与直线的位置关系', '单选题', 2, '空间中，点与直线的位置关系有几种？', '2种', '点与直线的位置关系只有点在直线上和点在直线外这两种情况。', '易', 5, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, 'A. 1种  B. 2种  C. 3种  D. 4种\n', '[\" 1种\",\" 2种\",\" 3种\",\" 4种\"]');
INSERT INTO `tpa_homework_details` VALUES (179, NULL, NULL, 20, NULL, '数学', '空间直线与直线的位置关系', '单选题', 2, '不平行的两条直线的位置关系是？', 'C', '不平行的两条直线可能相交，也可能异面。', '易', 5, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, 'A. 相交  B. 异面  C. 相交或异面  D. 平行\n', '[\" 相交\",\" 异面\",\" 相交或异面\",\" 平行\"]');
INSERT INTO `tpa_homework_details` VALUES (180, NULL, NULL, 20, NULL, '数学', '空间直线与平面的位置关系', '单选题', 2, '直线(l)不在平面(alpha)内，则直线(l)与平面(alpha)的位置关系是？', 'D', '直线不在平面内，那么直线与平面可能平行，也可能相交 。', '易', 6, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, 'A. 平行  B. 相交  C. 异面  D. 平行或相交\n', '[\" 平行\",\" 相交\",\" 异面\",\" 平行或相交\"]');
INSERT INTO `tpa_homework_details` VALUES (181, NULL, NULL, 20, NULL, '数学', '空间平面与平面的位置关系', '单选题', 2, '若两个平面没有公共点，则这两个平面的位置关系是？', 'A', '根据平面与平面位置关系的定义，没有公共点的两个平面互相平行。', '易', 6, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, 'A. 平行  B. 相交  C. 异面  D. 重合\n', '[\" 平行\",\" 相交\",\" 异面\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (182, NULL, NULL, 20, NULL, '数学', '空间点、直线、平面位置关系的综合', '多选题', 2, '以下说法正确的是（  ）', 'ABD', '选项A，空间中两条相交直线确定一个平面，正确；选项B，直线在平面外包含直线与平面平行和直线与平面相交两种情况，正确；选项C，两个平面有三个公共点，若这三个点共线，则两平面相交，不一定重合，错误；选项D，空间中，一条直线与两条异面直线中的一条平行，则它与另一条异面或相交，正确。', '中', 8, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, 'A. 两条相交直线确定一个平面  B. 直线在平面外包含两种情况  C. 两个平面有三个公共点，则这两个平面重合  D. 一条直线与两条异面直线中的一条平行，则它与另一条异面或相交\n', '[\" 两条相交直线确定一个平面\",\" 直线在平面外包含两种情况\",\" 两个平面有三个公共点，则这两个平面重合\",\" 一条直线与两条异面直线中的一条平行，则它与另一条异面或相交\"]');
INSERT INTO `tpa_homework_details` VALUES (183, NULL, NULL, 20, NULL, '数学', '空间直线与平面位置关系判断', '多选题', 2, '已知直线(a)，平面(alpha)，以下能推出(aparallelalpha)的是（  ）', 'BC', '选项A，直线(a)与平面(alpha)内一条直线平行，当(asubsetalpha)时，推不出(aparallelalpha)；选项B，直线(a)与平面(alpha)内两条相交直线都没有公共点，符合直线与平面平行的判定条件，可以推出(aparallelalpha)；选项C，直线(a)不在平面(alpha)内，且与平面(alpha)没有公共点，根据定义可推出(aparallelalpha)；选项D，直线(a)与平面(alpha)内无数条直线平行，当(asubsetalpha)时，推不出(aparallelalpha) 。', '中', 8, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (184, NULL, NULL, 20, NULL, '数学', '空间点、直线、平面位置关系基本概念', '填空题', 2, '空间中两条异面直线所成角的范围是____。', '((0,frac{pi}{2}])', '根据异面直线所成角的定义，其范围是((0,frac{pi}{2}])。', '易', 7, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (185, NULL, NULL, 20, NULL, '数学', '空间直线与平面位置关系应用', '填空题', 2, '若直线(m)与平面(beta)平行，直线(m)上有一点(P)，过点(P)作与平面(beta)平行的直线有____条。', '1', '因为直线(mparallelbeta)，过直线(m)上一点(P)作与平面(beta)平行的直线，有且只有一条。', '易', 7, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (186, NULL, NULL, 20, NULL, '数学', '空间平面与平面位置关系证明', '简答题', 2, '已知平面(alpha)，(beta)，直线(asubsetalpha)，(bsubsetalpha)，(acap b = A)，(aparallelbeta)，(bparallelbeta)，求证：(alphaparallelbeta)。', '因为(asubsetalpha)，(bsubsetalpha)，(acap b = A)，所以(a)，(b)确定一个平面(alpha)。又因为(aparallelbeta)，(bparallelbeta)，且(a)，(b)是平面(alpha)内两条相交直线，根据平面与平面平行的判定定理，如果一个平面内有两条相交直线都平行于另一个平面，那么这两个平面平行，所以(alphaparallelbeta)。', '本题利用平面与平面平行的判定定理进行证明，关键在于找出平面(alpha)内两条相交直线都与平面(beta)平行这一条件。', '中', 10, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (187, NULL, NULL, 20, NULL, '数学', '空间点、直线、平面位置关系综合问题', '简答题', 2, '在正方体(ABCD - A_{1}B_{1}C_{1}D_{1})中，判断直线(A_{1}C)与平面(BDC_{1})的位置关系，并说明理由。', '直线(A_{1}C)与平面(BDC_{1})相交。理由如下：连接(AC)交(BD)于点(O)，连接(C_{1}O)。在正方体(ABCD - A_{1}B_{1}C_{1}D_{1})中，(O)为(AC)中点，(A_{1}C_{1}parallel AC)且(A_{1}C_{1}=AC)。在(triangle A_{1}C_{1}C)中，(O)为(AC)中点，(C_{1}O)在平面(BDC_{1})内，(A_{1}C)与(C_{1}O)相交于一点，所以直线(A_{1}C)与平面(BDC_{1})相交 。', '本题先通过连接辅助线找到平面(BDC_{1})内与直线(A_{1}C)相关的直线(C_{1}O)，再根据直线与直线的位置关系判断直线与平面的位置关系。', '中', 10, 1, '0', 0, 0, '2025-04-14 23:08:18', '2025-04-14 23:08:18', '2025-04-14 23:08:18', 1, NULL, NULL, NULL);
INSERT INTO `tpa_homework_details` VALUES (188, NULL, NULL, 9, 13, '个性化补充题', '空间点、直线、平面之间的位置关系', '单选题', 3, '空间中两条直线如果既不平行也不相交，那么它们的位置关系是？', 'C', '空间中两条直线如果既不平行也不相交，那么它们是异面直线。', '易', 10, 1, '0', 0, 0, '2025-04-14 23:28:08', NULL, NULL, 1, NULL, 'A. 重合  B. 相交  C. 异面  D. 平行\n', '[\" 重合\",\" 相交\",\" 异面\",\" 平行\"]');
INSERT INTO `tpa_homework_details` VALUES (189, NULL, NULL, 9, 13, '个性化补充题', '空间点、直线、平面之间的位置关系', '多选题', 3, '以下哪些是空间中两条直线可能的位置关系？', 'A,B,C', '空间中两条直线可能的位置关系有相交、平行、异面。', '中', 15, 1, '0', 0, 0, '2025-04-14 23:28:08', NULL, NULL, 1, NULL, 'A. 相交  B. 平行  C. 异面  D. 重合\n', '[\" 相交\",\" 平行\",\" 异面\",\" 重合\"]');
INSERT INTO `tpa_homework_details` VALUES (190, NULL, NULL, 9, 13, '个性化补充题', '空间点、直线、平面之间的位置关系', '填空题', 3, '空间中两条直线如果相交，那么它们有____个公共点。', '1', '空间中两条直线如果相交，那么它们有且只有一个公共点。', '易', 10, 1, '0', 0, 0, '2025-04-14 23:28:08', NULL, NULL, 1, NULL, NULL, NULL);
