INSERT INTO `tpa_homework_track` VALUES (149, 17, NULL, 21, 4, 2, '4', 15, '2025-04-11 13:22:16', '2025-04-11 13:22:30', '00:00:13', 1, '', '');
INSERT INTO `tpa_homework_track` VALUES (150, NULL, 9, 2, 12, 2, '空间中直线与直线的位置关系有相交、平行、异面。相交如墙角处的三条交线中任意两条相交；平行如黑板的上下两条边所在直线平行；异面如教室的一条侧棱与和它不相交的面对角线异面', 15, '2025-04-14 10:19:25', '2025-04-14 10:19:37', '00:00:12', 1, '', '');
