SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for school
-- ----------------------------
DROP TABLE IF EXISTS `school`;
CREATE TABLE `school`  (
  `school_id` int NOT NULL AUTO_INCREMENT COMMENT '学校唯一标识',
  `school_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '学校名称',
  `school_short_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '学校简称',
  `address` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '学校地址',
  `contact` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '学校数据录入时间',
  `is_active` tinyint NULL DEFAULT 1 COMMENT '是否启用：1=启用，0=停用',
  PRIMARY KEY (`school_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of school
-- ----------------------------

-- ----------------------------
-- Table structure for school_topic_mapping
-- ----------------------------
DROP TABLE IF EXISTS `school_topic_mapping`;
CREATE TABLE `school_topic_mapping`  (
  `mapping_id` int NOT NULL AUTO_INCREMENT COMMENT '映射ID',
  `school_id` int NOT NULL COMMENT '学校ID',
  `template_id` int NULL DEFAULT NULL COMMENT '知识点模板ID',
  `tss_id` int NULL DEFAULT NULL COMMENT '学校对应知识点ID（若覆盖）',
  `is_used` tinyint NULL DEFAULT 1 COMMENT '是否使用：1=使用，0=不使用',
  `is_customized` tinyint NULL DEFAULT 0 COMMENT '是否自定义：1=是，0=否',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`mapping_id`) USING BTREE,
  INDEX `school_id`(`school_id`) USING BTREE,
  INDEX `tss_id`(`tss_id`) USING BTREE,
  INDEX `tempId`(`template_id`) USING BTREE,
  CONSTRAINT `school_topic_mapping_ibfk_1` FOREIGN KEY (`school_id`) REFERENCES `school` (`school_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `school_topic_mapping_ibfk_3` FOREIGN KEY (`tss_id`) REFERENCES `topic_points` (`tss_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1685 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of school_topic_mapping
-- ----------------------------

-- ----------------------------
-- Table structure for student_class
-- ----------------------------
DROP TABLE IF EXISTS `student_class`;
CREATE TABLE `student_class`  (
  `sc_id` int NOT NULL AUTO_INCREMENT COMMENT '学生-班级关系id',
  `sid` int NOT NULL COMMENT '学生的id',
  `cid` int NOT NULL COMMENT '班级id',
  `is_exit` int NOT NULL DEFAULT 1 COMMENT '该学生是否被移除班级',
  `ranking` int NULL DEFAULT NULL COMMENT '该学生在该班级中的排名',
  `evaluation` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT 'AI对学生的综合评价',
  PRIMARY KEY (`sc_id`) USING BTREE,
  INDEX `student_id`(`sid`) USING BTREE,
  INDEX `classId`(`cid`) USING BTREE,
  CONSTRAINT `classId` FOREIGN KEY (`cid`) REFERENCES `tpa_class` (`cid`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `student_id` FOREIGN KEY (`sid`) REFERENCES `tpa_student` (`sid`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 81 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of student_class
-- ----------------------------

-- ----------------------------
-- Table structure for teaching_plans
-- ----------------------------
DROP TABLE IF EXISTS `teaching_plans`;
CREATE TABLE `teaching_plans`  (
  `plan_id` int NOT NULL COMMENT '教学计划id',
  `ts_id` int NOT NULL COMMENT '关联的课程',
  `school_id` int NOT NULL COMMENT '学校id',
  `tss_id` int NOT NULL COMMENT '定制知识点id',
  `temp_id` int NULL DEFAULT NULL COMMENT '模版知识点id',
  `plan_order` int NOT NULL COMMENT '教学顺序（数字越小越先教）',
  `teach_way` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '教学方式',
  `pre_result` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '预期成果',
  `role` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该知识点对课程目标起到的作用和地位',
  PRIMARY KEY (`plan_id`) USING BTREE,
  INDEX `p_tsid`(`ts_id`) USING BTREE,
  INDEX `schoolid`(`school_id`) USING BTREE,
  INDEX `tssid`(`tss_id`) USING BTREE,
  INDEX `tempId`(`temp_id`) USING BTREE,
  CONSTRAINT `p_tsid` FOREIGN KEY (`ts_id`) REFERENCES `tpa_subject` (`ts_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `schoolid` FOREIGN KEY (`school_id`) REFERENCES `school` (`school_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `tempId` FOREIGN KEY (`temp_id`) REFERENCES `topic_templates` (`template_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `tssid` FOREIGN KEY (`tss_id`) REFERENCES `topic_points` (`tss_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of teaching_plans
-- ----------------------------

-- ----------------------------
-- Table structure for topic_points
-- ----------------------------
DROP TABLE IF EXISTS `topic_points`;
CREATE TABLE `topic_points`  (
  `tss_id` int NOT NULL AUTO_INCREMENT COMMENT '知识点唯一ID',
  `ts_id` int NOT NULL COMMENT '关联课程ID',
  `school_id` int NOT NULL COMMENT '学校ID',
  `template_id` int NULL DEFAULT NULL COMMENT '关联的知识点模板ID（若为复用模板）',
  `top_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '一级主题',
  `secondary_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '二级主题',
  `defined_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '老师自定义二级主题（覆盖模板）',
  `content` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '知识点内容（覆盖模板或新增内容）',
  `level` tinyint NOT NULL COMMENT '知识点层级(1-5)',
  `is_template` tinyint NULL DEFAULT 0 COMMENT '是否直接使用模板：1=是，0=否',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`tss_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1102 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of topic_points
-- ----------------------------

-- ----------------------------
-- Table structure for topic_relations
-- ----------------------------
DROP TABLE IF EXISTS `topic_relations`;
CREATE TABLE `topic_relations`  (
  `relation_id` int NOT NULL AUTO_INCREMENT COMMENT '知识点关系ID',
  `parent_tss_id` int NULL DEFAULT NULL COMMENT '父知识点ID（若为一级则为空）',
  `child_tss_id` int NOT NULL COMMENT '子知识点ID',
  `relation_type` tinyint NULL DEFAULT NULL COMMENT '关系类型：1=层级父子，2=关联关系，3=跨章节关系',
  `ts_id` int NOT NULL COMMENT '关联课程ID',
  `school_id` int NOT NULL COMMENT '学校id',
  `is_template` tinyint(1) UNSIGNED ZEROFILL NULL DEFAULT NULL COMMENT '是否基于模板关系：1=是，0=否',
  `template_relation_id` int NULL DEFAULT NULL COMMENT '关联的模板关系ID（若基于模板）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '关系创建时间',
  `relation_desc` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '关系描述',
  PRIMARY KEY (`relation_id`) USING BTREE,
  INDEX `tsid`(`ts_id`) USING BTREE,
  INDEX `school_id`(`school_id`) USING BTREE,
  INDEX `child_tssid`(`child_tss_id`) USING BTREE,
  INDEX `parent_tssid`(`parent_tss_id`) USING BTREE,
  CONSTRAINT `school_id` FOREIGN KEY (`school_id`) REFERENCES `school` (`school_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `tsid` FOREIGN KEY (`ts_id`) REFERENCES `tpa_subject` (`ts_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 809 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of topic_relations
-- ----------------------------

-- ----------------------------
-- Table structure for topic_template_relations
-- ----------------------------
DROP TABLE IF EXISTS `topic_template_relations`;
CREATE TABLE `topic_template_relations`  (
  `template_relation_id` int NOT NULL AUTO_INCREMENT COMMENT '模板关系ID',
  `parent_template_id` int NULL DEFAULT NULL COMMENT '父知识点模板ID',
  `child_template_id` int NOT NULL COMMENT '子知识点模板ID',
  `relation_type` tinyint NULL DEFAULT NULL COMMENT '关系类型：1=层级父子，2=关联关系',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `relation_desc` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '关系描述',
  `orderNum` int NULL DEFAULT NULL COMMENT '排序序号用于同一层级的排序',
  PRIMARY KEY (`template_relation_id`) USING BTREE,
  INDEX `parent_template_id`(`parent_template_id`) USING BTREE,
  INDEX `child_template_id`(`child_template_id`) USING BTREE,
  CONSTRAINT `topic_template_relations_ibfk_1` FOREIGN KEY (`parent_template_id`) REFERENCES `topic_templates` (`template_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `topic_template_relations_ibfk_2` FOREIGN KEY (`child_template_id`) REFERENCES `topic_templates` (`template_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of topic_template_relations
-- ----------------------------

-- ----------------------------
-- Table structure for topic_templates
-- ----------------------------
DROP TABLE IF EXISTS `topic_templates`;
CREATE TABLE `topic_templates`  (
  `template_id` int NOT NULL AUTO_INCREMENT COMMENT '知识点模板ID',
  `ts_id` int NOT NULL COMMENT '该知识点所属的课程',
  `top_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '一级主题',
  `secondary_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '二级主题',
  `content` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '知识点内容',
  `level` tinyint NOT NULL COMMENT '知识点层级(1-5)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`template_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of topic_templates
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_class
-- ----------------------------
DROP TABLE IF EXISTS `tpa_class`;
CREATE TABLE `tpa_class`  (
  `cid` int NOT NULL AUTO_INCREMENT COMMENT '班级的id',
  `tid` int NOT NULL COMMENT '该班级的老师id1',
  `person` int NULL DEFAULT 0 COMMENT '班级人数',
  `c_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '班级名称1',
  `c_subject` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '班级教学科目1',
  `class_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '班级特殊的编码，自动生成',
  `short_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '班级短码（加课码）',
  PRIMARY KEY (`cid`) USING BTREE,
  INDEX `teacherId`(`tid`) USING BTREE,
  INDEX `cid`(`cid`) USING BTREE,
  CONSTRAINT `tid` FOREIGN KEY (`tid`) REFERENCES `tpa_teacher` (`uid`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_class
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_design_before
-- ----------------------------
DROP TABLE IF EXISTS `tpa_design_before`;
CREATE TABLE `tpa_design_before`  (
  `dc_id` int NOT NULL AUTO_INCREMENT COMMENT '教学设计前置数据的id',
  `td_id` int NOT NULL COMMENT '关联的教学设计',
  `analysis_from` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '学期分析依据数据来源（verchar）作业或者预习任务的id，使用逗号隔开',
  `analysis_result` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'AI根据学生完成学习任务产生的数据来进行分析，并生成结论告诉老师该如何进行教学',
  `knowledge_analysis` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'Ai根据教学设计的两个主题来预测该教学设计可能涉及到的内容',
  `photo` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该教学设计可能使用的图片',
  `video` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该教学设计可能使用的视频资源',
  `interaction_analysis` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '上节课的互动数据分析结果和建议，需要包含上节课的主题',
  `preview_result` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '预习任务数据分析结果',
  PRIMARY KEY (`dc_id`) USING BTREE,
  INDEX `design_id`(`td_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_design_before
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_homework
-- ----------------------------
DROP TABLE IF EXISTS `tpa_homework`;
CREATE TABLE `tpa_homework`  (
  `hid` int NOT NULL AUTO_INCREMENT COMMENT '作业id',
  `author_id` int NOT NULL COMMENT '作业创建者的id',
  `cid` int NULL DEFAULT NULL COMMENT '（发布的时候再设置）班级的id，和班级进行绑定，以班级为单位对作业进行区分',
  `h_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '作业名称，可以随意取',
  `h_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '作业一级主题（主题可以限制知识点的范围）',
  `secondary_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '二级主题，和教学设计的那两个字段作用一样',
  `explanation` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '作业说明（可选）',
  `score` int NOT NULL COMMENT '作业总分',
  `complate` int NOT NULL DEFAULT 0 COMMENT '完成人数',
  `uncomplate` int NULL DEFAULT NULL COMMENT '未完成人数',
  `quantity` int NOT NULL COMMENT '题目数量',
  `create_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '作业创建时间（发布的时候再设置）',
  `deadline` datetime NULL DEFAULT NULL COMMENT '截止时间（后续发布后再设置截止时间）',
  `state` tinyint NOT NULL DEFAULT 0 COMMENT '作业状态，0：未发布，已发布：1，已结束：-1',
  `problem_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '（必须有）题目类型（选择题/填空题/简答题/混合题型的话使用字符串和逗号连接）',
  `is_open` tinyint NOT NULL DEFAULT 1 COMMENT '是否公开，0不公开，1公开',
  `h_type` tinyint NOT NULL DEFAULT 0 COMMENT '作业类型，0：普通作业，1：考试',
  `difficulty` varchar(225) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '作业的难度，可以选多种难度',
  PRIMARY KEY (`hid`) USING BTREE,
  INDEX `teacherId`(`author_id`) USING BTREE,
  CONSTRAINT `author_id` FOREIGN KEY (`author_id`) REFERENCES `tpa_teacher` (`uid`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_homework
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_homework_details
-- ----------------------------
DROP TABLE IF EXISTS `tpa_homework_details`;
CREATE TABLE `tpa_homework_details`  (
  `qid` int NOT NULL AUTO_INCREMENT COMMENT '题目的id',
  `hid` int NULL DEFAULT NULL COMMENT '关联的作业（原始属于的作业）',
  `other_hid` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该题目关联的其他作业',
  `pt_id` int NULL DEFAULT NULL COMMENT '关联的预习任务id预习任务的预习题、补充题都可以放到这张表中',
  `sid` int NULL DEFAULT NULL COMMENT '学生的id，只有该条数据是个性化推荐的就必须和唯一的学生匹配',
  `subject` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '表示该题目属于哪一个课程，方便后续自动匹配题库',
  `q_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '题目的知识点',
  `q_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '题目的类型（1:单选, 2:多选, 3:填空, 4:简答）',
  `q_from` tinyint NOT NULL DEFAULT -1 COMMENT '不可为null,题目来源1：作业/考试，2：预习任务预习题，3：补充题，-1：表示不属于任何作业',
  `q_content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '题目的内容',
  `correct_answer` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '题目的标准答案1',
  `answer_analysis` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '题目解析',
  `q_defficult` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '题目的难度',
  `default_score` int NOT NULL COMMENT '题目默认分值1',
  `usage_count` int NOT NULL DEFAULT 1 COMMENT '记录该题目被使用的次数(前提是题目是公开的)',
  `avg_correct_rate` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '历史平均准确率gai',
  `complete_time` int NOT NULL DEFAULT 0 COMMENT '该题目被完成的次数1gai',
  `correct_time` int NOT NULL DEFAULT 0 COMMENT '被回答正确的次数（同上，不考虑公开的情况）1gai',
  `create_time` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '题目创建/生成的时间',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '题目被修改的时间',
  `review_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '审核通过时间（统一修改为作业发布时间）',
  `is_delete` tinyint NOT NULL DEFAULT 1 COMMENT '软删除，1没删除，0删除',
  `q_hash` int NULL DEFAULT NULL COMMENT '题目的相识度hash值',
  `selections` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '如果该题是选择题（单选，多选）,这个字段就记录选项，方便后续渲染',
  `select_option` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '选择题选项的json串',
  PRIMARY KEY (`qid`) USING BTREE,
  INDEX `homework_id`(`hid`) USING BTREE,
  INDEX `preview_id`(`pt_id`) USING BTREE,
  CONSTRAINT `homeworkId` FOREIGN KEY (`hid`) REFERENCES `tpa_homework` (`hid`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `previewId` FOREIGN KEY (`pt_id`) REFERENCES `tpa_preview_task` (`pt_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 397 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_homework_details
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_homework_summary
-- ----------------------------
DROP TABLE IF EXISTS `tpa_homework_summary`;
CREATE TABLE `tpa_homework_summary`  (
  `tht_id` int NOT NULL AUTO_INCREMENT COMMENT '记录学生完成整个作业的情况',
  `hid` int NOT NULL COMMENT '这条数据关联的作业id1',
  `uid` int NOT NULL COMMENT '这条数据记录的用户id1',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '学生的姓名1',
  `complete_time` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '作业完成用时',
  `score` int NULL DEFAULT NULL COMMENT '作业得分',
  `complete_question` int NULL DEFAULT NULL COMMENT '完成的题目数',
  `question_num` int NOT NULL COMMENT '该作业的总题目数1',
  `mistake` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '错题',
  `is_complete` int NOT NULL DEFAULT 0 COMMENT '是否完成，0表示开始，1表示已完成，2表示已开始',
  `report` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT 'AI生成作业报告',
  PRIMARY KEY (`tht_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_homework_summary
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_homework_track
-- ----------------------------
DROP TABLE IF EXISTS `tpa_homework_track`;
CREATE TABLE `tpa_homework_track`  (
  `ht_id` int NOT NULL AUTO_INCREMENT COMMENT '跟踪信息id',
  `hid` int NULL DEFAULT NULL COMMENT '作业的id，后续匹配该作业的完成情况，为空的时候就表明这个是属于预习题的记录',
  `pt_id` int NULL DEFAULT NULL COMMENT '预习任务的id',
  `sid` int NOT NULL COMMENT '学生id',
  `qid` int NOT NULL COMMENT '题目id',
  `status` int NOT NULL DEFAULT 0 COMMENT '完成情况，0:未完成，1：正在完成中，2：已完成，后端设置一个端口检测学生在题目页面的行为，当停留超过30秒就视为正在完成，并记录开始的时间',
  `answer` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '学生的回答',
  `score` int NULL DEFAULT 0 COMMENT '评分或获取的分数',
  `attempt_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '学生开始尝试解题的时间',
  `completion_time` datetime NULL DEFAULT NULL COMMENT '学生完成这道题的时间',
  `time_spent` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '00:00:00' COMMENT '解题用时',
  `is_correct` tinyint NULL DEFAULT NULL COMMENT '是否正确',
  `mistake_case` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '错误的可能原因，完成该题就生成原因（由AI根据学生的答案进行分析）',
  `add_explanation` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '完成该题就生成，AI针对学生完成该题目的情况对学生进行额外知识的补充说明',
  PRIMARY KEY (`ht_id`) USING BTREE,
  INDEX `student_id`(`sid`) USING BTREE,
  INDEX `questio_id`(`qid`) USING BTREE,
  INDEX `homework_id`(`hid`) USING BTREE,
  CONSTRAINT `questionId` FOREIGN KEY (`qid`) REFERENCES `tpa_homework_details` (`qid`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `studentId` FOREIGN KEY (`sid`) REFERENCES `tpa_student` (`sid`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 269 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_homework_track
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_interaction
-- ----------------------------
DROP TABLE IF EXISTS `tpa_interaction`;
CREATE TABLE `tpa_interaction`  (
  `hd_id` int NOT NULL AUTO_INCREMENT COMMENT '互动id',
  `td_id` int NOT NULL COMMENT '关联的教学设计',
  `method` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '互动方式',
  `content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '互动内容',
  `replay` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '学生的回答，主观题就记录学生回答的文字；前端传数组，这里储存json',
  `viewpoint_num` int NULL DEFAULT NULL COMMENT '学生回答过程中生成有效的观点数',
  `participates` int NULL DEFAULT NULL COMMENT '参与人数，统计互动积极度',
  `correct` int NULL DEFAULT NULL COMMENT '回答对的人数',
  `ask_content` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '学生提问，json串',
  `deadline` datetime NULL DEFAULT NULL COMMENT '讨论的时长',
  `is_active` tinyint NOT NULL DEFAULT 1 COMMENT '活动的状态，1：可参与，0：不可参与',
  `question_type` int NULL DEFAULT NULL COMMENT '客观题或主观题（1客观，2主观）',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `answer` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '互动题目的答案集合',
  PRIMARY KEY (`hd_id`) USING BTREE,
  INDEX `teach_design`(`td_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_interaction
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_preview_task
-- ----------------------------
DROP TABLE IF EXISTS `tpa_preview_task`;
CREATE TABLE `tpa_preview_task`  (
  `pt_id` int NOT NULL AUTO_INCREMENT COMMENT '预习任务表',
  `cid` int NULL DEFAULT NULL COMMENT '班级id（发布的时候设置）',
  `author_id` int NOT NULL COMMENT '预习任务发布人',
  `preview_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '预习任务名称',
  `p_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '预习任务一级主题',
  `secondary_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '预习任务的二级主题',
  `p_explanation` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '预习任务额外说明',
  `preview_content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '预习任务资料内容（富文本）',
  `complete` int NULL DEFAULT 0 COMMENT '预习任务完成人数',
  `is_open` tinyint NOT NULL DEFAULT 1 COMMENT '预习任务资源是否公开',
  `create_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '预习任务发布时间',
  `deadline` datetime NULL DEFAULT NULL COMMENT '截止时间（后续发布再设置）',
  `active` tinyint NULL DEFAULT 0 COMMENT '预习任务状态（0：未发布，已发布：1，已结束：-1）',
  `problem` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '预习任务附加题，每题5分，直接将json串储存进来',
  `feedback` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '预习任务反馈',
  `by_time` int NULL DEFAULT NULL COMMENT '（发布的时候设置）老师给预习资料完成加一个限时，原则上学生完成预习资料不能超过这个时间',
  `questions_num` int NOT NULL COMMENT '预习题的数量',
  `questions_grade` int NOT NULL COMMENT '预习题总分',
  `problem_type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '题目类型（选择题/填空题/简答题/混合题型的话使用字符串和逗号连接）',
  PRIMARY KEY (`pt_id`) USING BTREE,
  INDEX `class_id`(`cid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_preview_task
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_preview_track
-- ----------------------------
DROP TABLE IF EXISTS `tpa_preview_track`;
CREATE TABLE `tpa_preview_track`  (
  `pid` int NOT NULL AUTO_INCREMENT COMMENT '学生预习任务完成情况记录id，该表一条数据就是一个学生完成一个预习任务的情况',
  `pt_id` int NOT NULL COMMENT '该条记录对应的预习任务的id',
  `sid` int NOT NULL COMMENT '该条记录对应的学生的id',
  `text_finish` int NOT NULL COMMENT '预习资料完成情况（0：还未完成，1：已完成）',
  `question_finish` int NOT NULL DEFAULT 0 COMMENT '预习题是否完成（0：未完成，1：已完成）这两个都是1才是完成了预习任务',
  `text_score` int NULL DEFAULT NULL COMMENT '预习资料题目得分',
  `data_inquiry` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '对预习资料的不懂的地方提出疑问',
  `start_time` datetime NOT NULL COMMENT '开始预习时间',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '结束预习时间',
  `question_score` int NULL DEFAULT NULL COMMENT '预习题得分',
  `complete_num` int NULL DEFAULT NULL COMMENT '完成的预习题目数量',
  `text_answer` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '预习资料题目回答，使用json格式进行储存',
  `question_num` int NOT NULL COMMENT '预习题数量',
  `supplement` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '补充资料，AI智能补充，该学生在这一个预习任务的情况个性化推荐资料',
  `add_question` int NULL DEFAULT NULL COMMENT '补充题目的个数，题目详情放到tpa_homework_details',
  `ai_analysis` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT 'AI对该学生预习情况的分析，包括对老师辅导该学生的建议',
  PRIMARY KEY (`pid`) USING BTREE,
  INDEX `preview_id`(`pt_id`) USING BTREE,
  INDEX `student_id`(`sid`) USING BTREE,
  CONSTRAINT `preview_task_id` FOREIGN KEY (`pt_id`) REFERENCES `tpa_preview_task` (`pt_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `student_info_Id` FOREIGN KEY (`sid`) REFERENCES `tpa_student` (`sid`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_preview_track
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_student
-- ----------------------------
DROP TABLE IF EXISTS `tpa_student`;
CREATE TABLE `tpa_student`  (
  `sid` int NOT NULL AUTO_INCREMENT COMMENT '学生id',
  `stu_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '学生姓名',
  `stu_stage` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '学生的年级',
  `stu_num` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '学生学号',
  PRIMARY KEY (`sid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_student
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_subject
-- ----------------------------
DROP TABLE IF EXISTS `tpa_subject`;
CREATE TABLE `tpa_subject`  (
  `ts_id` int NOT NULL AUTO_INCREMENT COMMENT '学科id',
  `school_id` int NOT NULL COMMENT '学校id，0表示不属于任何学校',
  `subject_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '课程名称',
  `subject_info` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '课程难度要求',
  `subject_stage` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '该课程所属的教育阶段',
  `grade` int NOT NULL COMMENT '教育阶段对应的年级',
  `volume` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '一' COMMENT '教材信息',
  `subtitle` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '课程类型，如，基础课程，核心课程，交叉课程，非计算机专业课程，系列课程',
  `customize` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '课程定制声明，如学校教学计划，适用阶段等',
  `subcode` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '课程编码',
  `is_open` tinyint(3) UNSIGNED ZEROFILL NOT NULL COMMENT '是否公开课程',
  `purpose` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '课程目标',
  PRIMARY KEY (`ts_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_subject
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_subject_syllabus
-- ----------------------------
DROP TABLE IF EXISTS `tpa_subject_syllabus`;
CREATE TABLE `tpa_subject_syllabus`  (
  `tss_id` int NOT NULL AUTO_INCREMENT COMMENT '知识点id',
  `ts_id` int NOT NULL COMMENT '学科id',
  `top_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '一级主题',
  `secondary_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '二级主题',
  `defined_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '老师自定义的二级主题，但是一级主题不可变，单元/章节不变',
  `school_id` int NOT NULL COMMENT '学校id，支持学校定义知识点',
  `content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '知识点内容',
  `level` tinyint NOT NULL COMMENT '知识点层级（1-5级）',
  PRIMARY KEY (`tss_id`) USING BTREE,
  INDEX `subject_id`(`ts_id`) USING BTREE,
  INDEX `sch_id`(`school_id`) USING BTREE,
  CONSTRAINT `sch_id` FOREIGN KEY (`school_id`) REFERENCES `school` (`school_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `ts_id` FOREIGN KEY (`ts_id`) REFERENCES `tpa_subject` (`ts_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 113 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_subject_syllabus
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_syllabus
-- ----------------------------
DROP TABLE IF EXISTS `tpa_syllabus`;
CREATE TABLE `tpa_syllabus`  (
  `syllabus_id` int NOT NULL AUTO_INCREMENT COMMENT '教学大纲id',
  `td_id` varchar(225) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '该教学设计大纲来自于哪一个教学设计',
  `author_id` varchar(225) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '000' COMMENT '教学设计的作者id，默认为000，表示经典模版，Ai生成的也填用户的id',
  `is_open` int NOT NULL DEFAULT 1 COMMENT '该大纲是否公开，0：不公开，1：公开',
  `content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '教学大纲的内容，为富文本的形式',
  `type` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '大纲的类型,该大纲属于哪一类课程（比如英语，数学等）',
  `create_time` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_delete` int NOT NULL DEFAULT 0 COMMENT '是否逻辑删除，0：未删除，1：删除',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_update` int NOT NULL DEFAULT 1 COMMENT '是否可以修改，1表示可以，0表示不可以',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '大纲的名称',
  `top_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '大纲一级标题',
  `secondary_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '大纲二级标题',
  PRIMARY KEY (`syllabus_id`) USING BTREE,
  INDEX `author_id`(`author_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_syllabus
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_teach_design
-- ----------------------------
DROP TABLE IF EXISTS `tpa_teach_design`;
CREATE TABLE `tpa_teach_design`  (
  `td_id` int NOT NULL AUTO_INCREMENT COMMENT '教学设计的id',
  `design_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '教学设计名称',
  `design_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '教学设计的一级主题（主题可以限制章节/单元）',
  `secondary_title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '教学设计的二级标题（具体的知识点，该单元里的某一个小节）',
  `subject` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '教学设计的学科',
  `author_id` int NOT NULL COMMENT '作者id',
  `is_open` int NULL DEFAULT 0 COMMENT '是否公开，0：不公开，1：公开',
  `content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '教学设计的内容（富文本）',
  `create_time` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `class_time` varchar(225) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '课时数',
  `target` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '授课对象（比如：高中一年级学生）',
  `last_modify` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '最近的修改时间',
  PRIMARY KEY (`td_id`) USING BTREE,
  INDEX `author_id`(`author_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_teach_design
-- ----------------------------

-- ----------------------------
-- Table structure for tpa_teacher
-- ----------------------------
DROP TABLE IF EXISTS `tpa_teacher`;
CREATE TABLE `tpa_teacher`  (
  `uid` int NOT NULL AUTO_INCREMENT COMMENT '教师id',
  `ts_id` int NULL DEFAULT NULL COMMENT '教授课程的id，可以为教师定制人工智能通识课，根据不同教师和学校的规则来定制',
  `account` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '教师账户名',
  `password` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账号密码',
  `teach_stage` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '教学的阶段默认是大学',
  `stage_num` int NOT NULL COMMENT '年级，默认大1',
  `teach_lesson` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '教学课程的名称',
  `phone` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '老师手机号',
  `sex` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '老师性别',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '老师姓名',
  `email` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '老师邮箱',
  `school_id` int NULL DEFAULT NULL COMMENT '老师所属学校id',
  `is_active` tinyint NULL DEFAULT NULL COMMENT '教师状态',
  `role` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '角色',
  PRIMARY KEY (`uid`) USING BTREE,
  INDEX `subjectId`(`ts_id`) USING BTREE,
  INDEX `schid`(`school_id`) USING BTREE,
  CONSTRAINT `schid` FOREIGN KEY (`school_id`) REFERENCES `school` (`school_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `subjectid` FOREIGN KEY (`ts_id`) REFERENCES `tpa_subject` (`ts_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tpa_teacher
-- ----------------------------

-- ----------------------------
-- Event structure for update_active_status
-- ----------------------------
DROP EVENT IF EXISTS `update_active_status`;
delimiter ;;
CREATE EVENT `update_active_status`
ON SCHEDULE
EVERY '1' HOUR STARTS '2025-02-20 22:08:02'
DO BEGIN
    UPDATE tpa_interaction
    SET is_active = 0
    WHERE deadline < NOW();
END
;;
delimiter ;

-- ----------------------------
-- Event structure for update_homeworkstate_status
-- ----------------------------
DROP EVENT IF EXISTS `update_homeworkstate_status`;
delimiter ;;
CREATE EVENT `update_homeworkstate_status`
ON SCHEDULE
EVERY '1' HOUR STARTS '2025-02-21 11:39:46'
DO BEGIN
    UPDATE tpa_homework
    SET state = 0
    WHERE deadline < NOW();
END
;;
delimiter ;

-- ----------------------------
-- Event structure for update_previewactive_status
-- ----------------------------
DROP EVENT IF EXISTS `update_previewactive_status`;
delimiter ;;
CREATE EVENT `update_previewactive_status`
ON SCHEDULE
EVERY '1' HOUR STARTS '2025-04-03 16:53:24'
DO BEGIN
    UPDATE tpa_preview_task tpt
    SET tpt.active=0
    WHERE tpt.deadline < NOW();
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table tpa_homework
-- ----------------------------
DROP TRIGGER IF EXISTS `update_homework_status`;
delimiter ;;
CREATE TRIGGER `update_homework_status` BEFORE UPDATE ON `tpa_homework` FOR EACH ROW BEGIN
    IF NEW.deadline IS NULL THEN
        SET NEW.state = 0;
    ELSEIF NEW.deadline < NOW() THEN
        SET NEW.state = -1;
    ELSE
        SET NEW.state = 1;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table tpa_homework_details
-- ----------------------------
DROP TRIGGER IF EXISTS `updateRate`;
delimiter ;;
CREATE TRIGGER `updateRate` BEFORE UPDATE ON `tpa_homework_details` FOR EACH ROW BEGIN
    IF OLD.correct_time != NEW.correct_time OR OLD.complete_time != NEW.complete_time THEN
        SET NEW.avg_correct_rate = 
            CASE 
                WHEN NEW.complete_time > 0 THEN NEW.correct_time / NEW.complete_time
                ELSE 0
            END;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table tpa_homework_track
-- ----------------------------
DROP TRIGGER IF EXISTS `updateDetials`;
delimiter ;;
CREATE TRIGGER `updateDetials` AFTER UPDATE ON `tpa_homework_track` FOR EACH ROW BEGIN
    IF NEW.is_correct IS NOT NULL THEN
        UPDATE tpa_homework_details thd
        SET
            thd.complete_time = thd.complete_time + 1,
            thd.correct_time = 
                CASE 
                    WHEN NEW.is_correct = 1 THEN thd.correct_time + 1
                    WHEN NEW.is_correct = 0 THEN thd.correct_time
                END
        WHERE thd.qid = NEW.qid;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table tpa_interaction
-- ----------------------------
DROP TRIGGER IF EXISTS `update_question_status`;
delimiter ;;
CREATE TRIGGER `update_question_status` BEFORE UPDATE ON `tpa_interaction` FOR EACH ROW BEGIN
    IF NEW.deadline < NOW() THEN
        SET NEW.is_active = 0;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table tpa_preview_task
-- ----------------------------
DROP TRIGGER IF EXISTS `update_preview_active`;
delimiter ;;
CREATE TRIGGER `update_preview_active` BEFORE UPDATE ON `tpa_preview_task` FOR EACH ROW BEGIN
    IF NEW.deadline IS NULL THEN
        SET NEW.active = 0;
    ELSEIF NEW.deadline < NOW() THEN
        SET NEW.active = -1;
    ELSE
        SET NEW.active = 1;
    END IF;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
